function currentPrdPageKey(){
 const p=state.page.split('/');
 if(state.page==='list/create')return`create-${['basic','editor','recipients','publish'][state.step-1]||'basic'}`;
 if(state.page==='templates/create'||state.page.startsWith('templates/edit/'))return`template-${['basic','editor','recipients','publish'][state.step-1]||'basic'}`;
 if(state.page==='templates')return`templates-${state.templateTab==='question'?'question':'survey'}`;
 if(state.page.startsWith('list/response/'))return'list-response';
 if(state.page.startsWith('list/fill/'))return'list-fill';
 if(state.page.startsWith('all-surveys/'))return'all-surveys-detail';
 if(state.page.startsWith('stats/detail/'))return'stats-detail';
 if(state.page.startsWith('stats/people/'))return'stats-people';
 if(state.page==='mobile/fill')return'mobile-fill-list';
 if(p[0]==='mobile'&&p[1]==='fill'&&p[2])return'mobile-form';
 if(p[0]==='mobile'&&p[1]==='complete')return'mobile-complete';
 if(p[0]==='mobile')return`mobile-${p[1]||'fill-list'}`;
 return state.page;
}
function prdTrack(event,entryType,key,closeMethod=''){
 const record={event,portal:state.portal,device:state.preview,page_key:currentPrdPageKey(),overlay_key:entryType==='overlay'?key:'',entry_type:entryType,close_method:closeMethod,timestamp:formatSystemTime()};
 window.__prdEvents=window.__prdEvents||[];window.__prdEvents.push(record);
}
function prdFeatureRows(rule){return[
 ['规则入口','查看当前界面 PRD',`点击右上角“prd”打开《${rule.title}》规则，不改变当前业务状态。`,'P0','按钮固定小写'],
 ['字段口径','字段限制与来源',`逐字段展示输入限制、前端来源、计算方式和空值处理。`,'P0',`${rule.fields.length} 个字段口径`],
 ['交互反馈','关闭与恢复','支持关闭按钮、遮罩和 Escape；关闭后返回原界面。','P0','不触发页面重渲染']
]}
function prdTable(headers,rows,klass=''){
 return `<div class="prd-table-wrap"><table class="prd-table ${klass}"><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`
}
function renderPrdDocument(rule,key,entryType){
 const features=prdTable(['功能模块','功能点','需求描述','优先级（P0 / P1 / P2）','备注说明'],prdFeatureRows(rule));
 const fields=prdTable(['字段/信息','限制与展示规则','当前原型来源'],rule.fields||[],'prd-field-table');
 return `<article class="prd-document"><header class="prd-document-head"><div><small>${entryType==='page'?'页面':'弹窗'}规则 · ${esc(key)}</small><h2>${esc(rule.title)}</h2></div><button type="button" class="prd-close" aria-label="关闭 PRD 规则">×</button></header><section><h3>1. 背景与目标</h3><p>${esc(rule.goal)}</p></section><section><h3>2. 用户与使用场景</h3><p>供产品、设计、前端、后端和测试人员在当前原型上下文中核对界面规则。</p></section><section><h3>3. 需求范围</h3><h4>In Scope</h4><p>当前${entryType==='page'?'页面':'覆盖层'}的字段、展示、操作、状态和异常规则。</p><h4>Out of Scope</h4><p>后端接口实现、数据库持久化、入口展示页及原型端/设备切换器。</p></section><section><h3>4. 功能需求列表</h3>${features}</section><section><h3>5. 核心流程与交互说明</h3><p>进入当前界面后按字段规则展示或录入数据；操作按钮根据当前状态生效；离开、取消或关闭时遵循原业务流程。</p>${fields}</section><section><h3>6. 异常场景与边界条件</h3><p>无权限、数据不存在或已删除时展示空态；非法输入阻止提交并给出明确提示；动态 ID 不改变本规则的字段口径。</p></section><section><h3>7. 数据口径与埋点需求</h3><p>字段来源以上表为准。打开、关闭分别记录 prd_rule_open、prd_rule_close，公共参数包含 portal、device、page_key、overlay_key、entry_type 和 timestamp。</p></section><section><h3>8. 风险、依赖与限制</h3><p>当前数据为前端原型数据或派生结果；规则描述不代表已存在后端接口。PRD 查看层不得修改原业务状态。</p></section><section><h3>9. 验收标准</h3><p>字段限制与实际校验一致；展示字段可追溯到明确前端来源；按钮不遮挡原操作；关闭后原界面及输入内容保持不变。</p></section></article>`
}
function closePrd(method='button'){
 const layer=$('#prd-layer');if(!layer?.classList.contains('show'))return;
 prdTrack('prd_rule_close',layer.dataset.entryType||'page',layer.dataset.ruleKey||'',method);layer.classList.remove('show');layer.innerHTML='';
}
function openPrd(key,entryType='page'){
 const rule=(entryType==='overlay'?PRD_OVERLAY_RULES:PRD_PAGE_RULES)[key];
 const fallback={title:'当前界面暂无 PRD 配置',goal:`未找到键为“${key}”的规则配置。`,fields:[['规则键','只读；用于定位缺失配置。',key]]};
 const layer=$('#prd-layer');if(!layer)return;
 layer.dataset.entryType=entryType;layer.dataset.ruleKey=key;layer.innerHTML=renderPrdDocument(rule||fallback,key,entryType);layer.classList.add('show');
 prdTrack('prd_rule_open',entryType,key);$('.prd-close',layer)?.focus();$('.prd-close',layer).onclick=()=>closePrd('button');layer.onclick=e=>{if(e.target===layer)closePrd('mask')};
}
function prdButton(key,entryType='page',extraClass=''){return `<button type="button" class="prd-trigger ${extraClass}" aria-label="查看当前${entryType==='page'?'页面':'弹窗'} PRD 规则" data-prd-key="${esc(key)}" data-prd-entry="${entryType}">prd</button>`}
function bindPrdButton(button){if(!button||button.dataset.prdBound)return;button.dataset.prdBound='1';prdTrack('prd_entry_expose',button.dataset.prdEntry||'page',button.dataset.prdKey||'');button.onclick=e=>{e.stopPropagation();openPrd(button.dataset.prdKey,button.dataset.prdEntry||'page')}}
function installPagePrdButton(){
 const key=currentPrdPageKey(),view=$('#view');if(!view)return;
 const mobileHead=$('.stats-mobile-head',view),pageActions=$('.page-head .head-actions',view);let host=pageActions;
 if(mobileHead){mobileHead.insertAdjacentHTML('beforeend',prdButton(key,'page','mobile-prd-trigger'));host=mobileHead}else if(!host){view.insertAdjacentHTML('afterbegin',prdButton(key,'page','floating-prd-trigger'));host=view}
 else host.insertAdjacentHTML('afterbegin',prdButton(key));
 bindPrdButton($(`[data-prd-entry="page"][data-prd-key="${key}"]`,host));
 const choice=$('.mobile-choice-sheet',view),question=$('.mobile-question-sheet',view),picker=$('.mobile-template-options',view);
 if(choice)decorateOverlay(choice,'settings-choice');if(question)decorateOverlay(question,'question-picker');if(picker)decorateOverlay(picker,'template-type-picker');
}
function decorateOverlay(container,key){if(!container||$('.overlay-prd-trigger',container))return;container.insertAdjacentHTML('afterbegin',prdButton(key,'overlay','overlay-prd-trigger'));bindPrdButton($('.overlay-prd-trigger',container))}
function scanOverlayPrd(){
 const selectors=[['.question-picker','question-picker'],['.question-template-modal','question-template'],['.qr-result','qr'],['.qr-phone-shell','qr-preview'],['.stats-action-sheet','stats-actions'],['.mobile-choice-sheet','settings-choice'],['.mobile-question-sheet','question-picker'],['.stat-preview-modal','asset-preview'],['.mobile-template-options','template-type-picker']];
 selectors.forEach(([selector,key])=>$$(selector).forEach(node=>decorateOverlay(node,key)));
 $$('#modal .modal').forEach(node=>{if(!$('.overlay-prd-trigger',node))decorateOverlay(node,$('#survey-type-name',node)?'survey-type':'confirmation')});
}
function applyRuntimeConstraints(root=document){
 const maxLengths={'#filter-title':50,'#filter-owner':50,'#all-filter-title':50,'#all-filter-owner':50,'#template-name':50,'#survey-type-keyword':50,'#object-name':50,'#recipient-search':50,'#survey-title':50,'#survey-description':500,'#prop-title':200,'#prop-options':1019,'#mobile-title':50,'#mobile-description':500,'#question-template-title':50,'#question-template-options':1019,'#response-answer-2':200,'#response-answer-3':500};
 Object.entries(maxLengths).forEach(([selector,value])=>$(selector,root)?.setAttribute('maxlength',String(value)));
}
function formatSystemTime(value=new Date()){const d=value instanceof Date?value:new Date(value);const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`}
function mount(){const root=$('#app'); if(!root)return; state.portal=root.dataset.portal;state.preview=sessionStorage.getItem('survey-preview')||(innerWidth<=720?'mobile':'pc'); state.questions=defaultQuestions(); window.addEventListener('hashchange',route);document.addEventListener('keydown',e=>{if(e.key==='Escape')closePrd('escape')});new MutationObserver(()=>{scanOverlayPrd();applyRuntimeConstraints(root)}).observe(root,{childList:true,subtree:true}); route()}
function route(){if($('#prd-layer')?.classList.contains('show'))closePrd('route_change');state.page=(location.hash||'#dashboard').slice(1).split('?')[0];if(state.page==='create'){location.replace('#list/create');return}if(state.portal==='bureau'&&state.preview==='pc'&&state.page==='stats'){location.replace('#all-surveys');return}renderShell()}
function renderShell(){const c=CONFIG[state.portal],mobile=state.preview==='mobile',activePage=state.page.startsWith('list/')?'list':state.page.startsWith('all-surveys/')?'all-surveys':state.page.startsWith('templates/')?'templates':state.page.startsWith('stats')?'stats':state.page; document.title=`${c.org} · 教育问卷调研`; $('#app').innerHTML=`<div class="prototype-shell ${mobile?'device-mobile':'device-pc'}"><div class="prototype-switch"><div><button class="${state.portal==='bureau'?'active':''}" data-portal-switch="bureau">教育局端</button><button class="${state.portal==='school'?'active':''}" data-portal-switch="school">学校端</button></div><div><button class="${!mobile?'active':''}" data-device-switch="pc">PC端</button><button class="${mobile?'active':''}" data-device-switch="mobile">移动端</button></div></div><div class="device-stage"><div class="app portal-${state.portal} ${(state.page.startsWith('stats')||state.page.startsWith('mobile/'))?'stats-app':''}"><aside class="sidebar"><div class="side-brand"><span class="brand-mark">调</span><div>教育问卷调研<div class="side-caption">${c.name}</div></div></div><nav class="side-menu">${c.menus.map(m=>`<a class="menu-item ${activePage===m[0]?'active':''}" href="#${m[0]}"><span>${m[1]}</span></a>`).join('')}</nav></aside><main class="main"><header class="topbar"><div><div class="org-title">${c.org}</div><div class="org-sub">教育问卷调研 · ${c.name}</div></div><div class="top-actions"><span class="avatar">${c.user[0]}</span><span>${c.user}</span></div></header><section class="content" id="view">${renderPage()}</section></main></div></div></div><div class="modal-mask" id="modal"></div><div class="prd-mask" id="prd-layer"></div><div class="toast" id="toast"></div>`;bind();installPagePrdButton();if(state.page==='list')applySurveyFilters();if(state.page==='all-surveys')applyAllSurveyFilters()}
function deviceSwitchPage(target){const pcCreation=state.page==='list/create'||state.page==='templates/create'||state.page.startsWith('templates/edit/'),mobileCreation=['mobile/create','mobile/settings','mobile/recipients'].includes(state.page);if(target==='mobile'){if(pcCreation)return state.step>=4?'mobile/settings':state.step===3?'mobile/recipients':'mobile/create';if(state.page.startsWith('mobile/')||state.page.startsWith('stats'))return state.page;return'mobile/fill'}if(mobileCreation){state.step=state.page==='mobile/settings'?4:state.page==='mobile/recipients'?3:(state.questions.length?2:1);return'list/create'}if(state.page.startsWith('stats'))return state.page;return state.page.startsWith('mobile/')?'dashboard':state.page}
function switchDevice(target){if(target===state.preview)return;const nextPage=deviceSwitchPage(target);state.preview=target;sessionStorage.setItem('survey-preview',target);if(nextPage===state.page)renderShell();else location.hash=nextPage}
function normalizeSurveyChannels(){CONFIG[state.portal].surveys.forEach((s,i)=>{if(!s.channel)s.channel=i===0&&s.owner===currentUserName()?state.channel:s.type==='公开问卷'?'public':'internal';if(!s.frequency)s.frequency=s.type==='每日收集'?'daily':'single'})}
function renderPage(){normalizeSurveyChannels();if(state.preview==='mobile'&&!state.page.startsWith('mobile/')&&!state.page.startsWith('stats'))state.page='mobile/fill';if(state.page.startsWith('mobile/'))return mobileRoutePage();if(state.page.startsWith('list/response/'))return responseDetailPage();if(state.page.startsWith('list/fill/'))return responseFillPage();if(state.page.startsWith('all-surveys/'))return allSurveyDetailPage();if(state.page.startsWith('stats/'))return statsRoutePage();if(state.page.startsWith('templates/edit/'))return createTemplatePage();switch(state.page){case'dashboard':return dashboard();case'list':return listPage();case'list/create':return createPage();case'all-surveys':return allSurveysPage();case'templates':return templatesPage();case'templates/create':return createTemplatePage();case'stats':return state.portal==='school'&&state.preview==='pc'?allSurveysPage():statsPage();case'survey-types':return surveyTypesPage();case'auth':return authPage();case'approval':return approvalPage();default:return dashboard()}}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1></div><div class="head-actions">${actions}</div></div>`}
function paginationComponent(key,pages=2){return `<div class="pagination" data-pagination="${key}"><button class="page-btn" data-page-action="prev" aria-label="上一页">‹</button>${Array.from({length:pages},(_,i)=>`<button class="page-btn ${i===0?'active':''}" data-page="${i+1}">${i+1}</button>`).join('')}<button class="page-btn" data-page-action="next" aria-label="下一页">›</button></div>`}
function sentCount(s){return s.channel==='internal'?s.total:'—'}
function submittedCount(s){return s.done||0}
function dashboard(){const c=CONFIG[state.portal], school=state.portal==='school';return `${pageHead('首页',`欢迎回来，${c.user.split(' · ')[0]}。这里是${school?'学校':'区域'}问卷运行概览。`)}<div class="stats-grid">${c.stats.map(s=>`<div class="stat-card"><div class="stat-label">${s[0]}</div><div class="stat-value">${s[1]}</div></div>`).join('')}</div><div class="dashboard-grid"><div class="card"><div class="card-title"><span>${school?'近7日答卷趋势':'近6月问卷与答卷趋势'}</span><span class="subtle">有效答卷</span></div><div class="chart-box">${[42,66,53,78,63,91,82].map((h,i)=>`<div class="bar-wrap"><i class="bar ${i%2?'alt':''}" style="height:${h}%"></i><span class="bar-label">${school?['周一','周二','周三','周四','周五','周六','周日'][i]:['2月','3月','4月','5月','6月','7月','8月'][i]}</span></div>`).join('')}</div></div><div class="card"><div class="card-title">${school?'年级完成情况':'重点学校参与情况'}</div>${(school?[['七年级',92],['八年级',86],['九年级',95],['教职工',88]]:[['实验学校',96],['第一小学',91],['第二中学',87],['城关小学',82],['民族中学',76]]).map(x=>`<div class="progress-row"><span>${x[0]}</span><div class="progress green"><i style="width:${x[1]}%"></i></div><b>${x[1]}%</b></div>`).join('')}</div></div><div class="dashboard-grid"><div class="card"><div class="card-title"><span>近期问卷</span><a href="#list" class="link-btn">全部问卷</a></div>${surveyTable(c.surveys.slice(0,4),true)}</div><div class="card"><div class="card-title">近期动态</div>${[['2026-8-13 16:24:08','王明发布了「秋季开学工作准备情况调查」'],['2026-8-13 15:50:36','实验学校完成率达到 96%'],['2026-8-13 14:18:22','系统生成了今日周期任务'],['2026-8-13 11:06:45','李静查看了教师问卷提交进度']].map(a=>`<div class="activity"><i class="activity-dot"></i><div>${a[1]}<div class="activity-time">${a[0]}</div></div></div>`).join('')}</div></div>`}
function surveyTable(rows,compact=false,view='published'){return `<div class="${compact?'compact-list':'table-wrap'}"><table class="data-table"><thead><tr><th class="index-col">序号</th><th>问卷名称</th><th>类型</th><th>发送人数</th><th>提交人数</th><th>状态</th>${compact?'':'<th>创建人</th><th>创建时间</th><th>操作</th>'}</tr></thead><tbody>${rows.map((s,i)=>`<tr data-id="${s.id}" data-title="${esc(s.title)}" data-owner="${esc(s.owner)}" data-type="${esc(s.type)}" data-status="${s.status}"><td class="index-col">${i+1}</td><td><div class="title-cell">${s.title}</div>${compact?`<div class="meta-line">${s.time}</div>`:''}</td><td>${s.type}</td><td>${sentCount(s)}</td><td>${submittedCount(s)}</td><td><span class="tag ${s.status}">${s.statusText}</span></td>${compact?'':`<td>${s.owner}</td><td class="nowrap">${s.createdAt}</td><td><div class="row-actions">${view==='received'?receivedActions(s):publishedActions(s)}</div></td>`}</tr>`).join('')}</tbody></table>${compact?paginationComponent('recent-surveys'):''}</div>`}
function publishedActions(s){const statusActions=s.status==='running'?'<button class="link-btn" data-action="pause">暂停</button><button class="link-btn danger" data-action="end">结束</button>':s.status==='paused'?'<button class="link-btn" data-action="resume">恢复</button><button class="link-btn danger" data-action="end">结束</button>':'',qrAction=s.status!=='draft'&&s.channel!=='internal'?`<button class="link-btn" data-survey-qr="${s.id}">二维码</button>`:'';return `<button class="link-btn" data-action="view-stats">问卷统计</button>${qrAction}${statusActions}<button class="link-btn danger" data-action="delete-survey">删除</button>`}
function responseRecords(s){return [...(MY_RESPONSES[state.portal]?.[s.id]||[])].filter(r=>r.valid!==false).sort((a,b)=>b.submittedAt.localeCompare(a.submittedAt))}
function localDateKey(value=new Date()){const d=value instanceof Date?value:new Date(value);const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}
function canCreateResponse(s){if(s.status!=='running')return false;const records=responseRecords(s);if(!records.length)return true;if(s.frequency==='unlimited')return true;if(s.frequency==='daily')return !records.some(r=>r.submittedAt.slice(0,10)===localDateKey());return false}
function receivedActions(s){const records=responseRecords(s),view=records.length?`<a class="link-btn" href="#list/response/${s.id}">查看</a>`:'';if(!canCreateResponse(s))return view;if(!records.length&&s.fillStatus==='in_progress')return `<a class="link-btn" href="#list/fill/${s.id}">继续填写</a>`;return `${view}<a class="link-btn" href="#list/fill/${s.id}">提交问卷</a>`}
function currentUserName(){return CONFIG[state.portal].user.split(' · ')[0]}
function listRows(){const surveys=CONFIG[state.portal].surveys.filter(s=>s.deleted!==1);return state.listView==='received'?surveys.filter(s=>s.received):surveys.filter(s=>s.owner===currentUserName())}
function listPage(){const rows=listRows(),f=state.listFilters;return `${pageHead('问卷管理','统一管理问卷状态、接收人员与发布进度。','<a class="btn primary" href="#list/create">+ 创建问卷</a>')}<div class="tabs">${[['received','我收到的'],['published','我发布的']].map(t=>`<button class="tab ${state.listView===t[0]?'active':''}" data-list-view="${t[0]}">${t[1]}</button>`).join('')}</div><div class="filter-card"><div class="toolbar filter-toolbar"><label class="filter-item"><span>问卷名称：</span><input id="filter-title" type="text" maxlength="50" value="${esc(f.title)}" placeholder="请输入问卷名称"></label><label class="filter-item"><span>创建人：</span><input id="filter-owner" type="text" maxlength="50" value="${esc(f.owner)}" placeholder="请输入创建人"></label><label class="filter-item"><span>问卷类型：</span><select id="filter-type" class="select">${filterOptions(['','系统定向','学校调查','内部调查','公开问卷','每日收集'],f.type)}</select></label><label class="filter-item"><span>问卷状态：</span><select id="filter-status" class="select">${filterOptions([['','全部'],['draft','草稿'],['running','进行中'],['paused','已暂停'],['ended','已结束']],f.status)}</select></label></div><span class="subtle" id="filter-count">共 ${rows.length} 条记录</span></div><div id="survey-table">${surveyTable(rows,false,state.listView)}${paginationComponent('survey-list')}</div>`}
function receivedSurveyFromRoute(index=2){const id=+state.page.split('/')[index];return CONFIG[state.portal].surveys.find(s=>s.id===id&&s.received)}
function frequencyText(value){return ({single:'仅提交一次',daily:'每日可提交一次',unlimited:'不限次数提交'})[value]||'仅提交一次'}
function responseTimestamp(){const d=new Date(),pad=n=>String(n).padStart(2,'0');return `${localDateKey(d)} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`}
function responseNotFound(){return `${pageHead('本人答卷','')}<a class="back-link" href="#list">← 返回问卷管理</a><div class="empty-state detail-empty"><b>未找到可查看的本人答卷</b><span>该问卷不存在、已移除或您不在接收范围内。</span></div>`}
function responseDetailPage(){const s=receivedSurveyFromRoute(),records=s?responseRecords(s):[];if(!s||!records.length)return responseNotFound();const selectedId=state.responseSelection[s.id],selected=records.find(r=>r.id===selectedId)||records[0];state.responseSelection[s.id]=selected.id;return `<a class="back-link" href="#list">← 返回问卷管理</a>${pageHead('本人答卷','')}<div class="response-detail-head"><div><h2>${esc(s.title)}</h2><p>${frequencyText(s.frequency)} · 共 ${records.length} 次提交</p></div><span class="tag ${s.status}">${s.statusText}</span></div><div class="my-response-layout"><aside class="response-history card"><div class="card-title">提交历史</div>${records.map((r,i)=>`<button class="response-history-item ${r.id===selected.id?'active':''}" data-action="select-my-response" data-survey-id="${s.id}" data-response-id="${r.id}"><b>第 ${records.length-i} 次提交</b><span>${r.submittedAt}</span><small>${r.id}</small></button>`).join('')}</aside><section class="response-answer card"><div class="response-answer-head"><div><h3>答卷内容</h3><p>提交时间：${selected.submittedAt}</p></div>${s.status==='running'&&s.allowModify?`<a class="btn" href="#list/fill/${s.id}/${selected.id}">修改本次答卷</a>`:''}</div><div class="answer-list">${selected.answers.map((a,i)=>`<div class="answer-item"><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(a[0])}</b><p>${esc(a[1])}</p></div></div>`).join('')}</div></section></div>`}
function responseFillPage(){const parts=state.page.split('/'),s=receivedSurveyFromRoute(),editingId=parts[3],editing=editingId?responseRecords(s||{}).find(r=>r.id===editingId):null;if(!s)return responseNotFound();if(editingId&&(!editing||s.status!=='running'||!s.allowModify))return `${pageHead('填写问卷','')}<a class="back-link" href="#list/response/${s.id}">← 返回本人答卷</a><div class="empty-state detail-empty"><b>当前答卷不可修改</b><span>仅进行中且允许提交后修改的问卷支持修改原答卷。</span></div>`;if(!editing&&!canCreateResponse(s))return `${pageHead('填写问卷','')}<a class="back-link" href="#list">← 返回问卷管理</a><div class="empty-state detail-empty"><b>当前不可新增提交</b><span>${s.status==='running'?`${frequencyText(s.frequency)}的提交次数已用完。`:'问卷已暂停或结束。'}</span></div>`;const answers=editing?.answers||[];return `<a class="back-link" href="${editing?`#list/response/${s.id}`:'#list'}">← ${editing?'返回本人答卷':'返回问卷管理'}</a>${pageHead(editing?'修改本次答卷':'提交问卷','')}<div class="response-form-card card"><div class="response-form-head"><h2>${esc(s.title)}</h2><p>${editing?`正在修改 ${editing.id}，保存后不会新增提交次数。`:`${frequencyText(s.frequency)}，本次提交将生成一条新的答卷记录。`}</p></div><div class="response-form"><label class="field required"><span>1. 您目前主要任教的学段是？</span><select id="response-answer-1"><option value="">请选择</option>${['小学','初中','高中'].map(x=>`<option ${answers[0]?.[1]===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field required"><span>2. 您在教学中使用过哪些数字化工具？</span><input id="response-answer-2" maxlength="200" value="${esc(answers[1]?.[1]||'')}" placeholder="请输入使用过的工具"></label><label class="field required"><span>3. 您希望获得哪些方面的培训支持？</span><textarea id="response-answer-3" maxlength="500" placeholder="请输入培训需求">${esc(answers[2]?.[1]||'')}</textarea></label></div><div class="footer-actions"><a class="btn" href="${editing?`#list/response/${s.id}`:'#list'}">取消</a><button class="btn primary" data-action="submit-my-response" data-survey-id="${s.id}" ${editing?`data-response-id="${editing.id}"`:''}>${editing?'保存修改':'确认提交'}</button></div></div>`}
function collectResponseAnswers(){return [['您目前主要任教的学段是？',$('#response-answer-1')?.value.trim()],['您在教学中使用过哪些数字化工具？',$('#response-answer-2')?.value.trim()],['您希望获得哪些方面的培训支持？',$('#response-answer-3')?.value.trim()]]}
function allSurveyRows(){return CONFIG[state.portal].surveys.filter(s=>s.deleted!==1)}
function allSurveysTable(rows){return `<div class="table-wrap"><table class="data-table all-surveys-table"><thead><tr><th class="index-col">序号</th><th>问卷名称</th><th>问卷类型</th><th>发送人数</th><th>提交人数</th><th>问卷状态</th><th>创建人员</th><th>创建时间</th><th>操作</th></tr></thead><tbody>${rows.map((s,i)=>`<tr data-id="${s.id}" data-title="${esc(s.title)}" data-owner="${esc(s.owner)}" data-created-date="${s.createdAt.slice(0,10)}" data-status="${s.status}"><td class="index-col">${i+1}</td><td><div class="title-cell">${esc(s.title)}</div></td><td>${esc(s.type)}</td><td>${sentCount(s)}</td><td>${submittedCount(s)}</td><td><span class="tag ${s.status}">${s.statusText}</span></td><td>${esc(s.owner)}</td><td class="nowrap">${s.createdAt}</td><td><div class="row-actions"><a class="link-btn" href="#all-surveys/${s.id}">查看详情</a><a class="link-btn" href="#stats/detail/${s.id}" data-stats-source="all-surveys">问卷统计</a></div></td></tr>`).join('')}<tr class="all-surveys-empty hidden"><td colspan="9"><div class="empty-state"><b>未找到符合条件的问卷</b><span>请调整筛选条件后重试</span></div></td></tr></tbody></table></div>`}
function allSurveysPage(){const rows=allSurveyRows(),f=state.allSurveyFilters,scope=state.portal==='bureau'?'当前教育局':'当前学校';return `${pageHead('全部问卷',`查看${scope}内所有人员创建的问卷，已删除问卷不展示。`)}<div class="filter-card all-survey-filter"><div class="toolbar filter-toolbar"><label class="filter-item"><span>问卷名称：</span><input id="all-filter-title" type="text" maxlength="50" value="${esc(f.title)}" placeholder="请输入问卷名称"></label><label class="filter-item"><span>创建人员：</span><input id="all-filter-owner" type="text" maxlength="50" value="${esc(f.owner)}" placeholder="请输入创建人员"></label><label class="filter-item"><span>创建时间：</span><div class="date-range"><input id="all-filter-start" type="date" value="${f.start}"><em>至</em><input id="all-filter-end" type="date" value="${f.end}"></div></label><label class="filter-item"><span>问卷状态：</span><select id="all-filter-status" class="select">${filterOptions([['','全部'],['draft','草稿'],['running','进行中'],['paused','已暂停'],['ended','已结束']],f.status)}</select></label></div><div class="filter-footer"><span class="subtle" id="all-filter-count">共 ${rows.length} 条记录</span><span class="filter-error" id="all-filter-error"></span></div></div><div id="all-surveys-table">${allSurveysTable(rows)}${paginationComponent('all-surveys')}</div>`}
function surveyDetailQuestions(s){const topics=s.type==='公开问卷'?['您对本次调查事项的总体评价是？','您最关注的问题是什么？','请填写您的意见或建议。']:['请选择您的所属范围。','您是否已完成相关工作？','请填写需协调解决的问题。'];return topics.map((q,i)=>`<div class="readonly-question"><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(q)}</b><p>${i===0?'单选题 · 必答':i===1?'单选题 · 必答':'填空题 · 选答'}</p></div></div>`).join('')}
function allSurveyDetailPage(){const id=Number(state.page.split('/')[1]),s=CONFIG[state.portal].surveys.find(x=>x.id===id&&x.deleted!==1);if(!s)return `<a class="back-link" href="#all-surveys">← 返回全部问卷</a><div class="empty-state detail-empty"><b>问卷不存在或无权查看</b><span>该问卷已删除、不属于当前组织，或链接无效。</span></div>`;const rate=s.total?Math.round(s.done/s.total*100):0,pending=Math.max(0,s.total-s.done);return `<a class="back-link" href="#all-surveys">← 返回全部问卷</a>${pageHead('问卷详情','只读查看问卷配置、接收人员与统计数据。')}<div class="detail-head"><div class="detail-title">${esc(s.title)}</div><div class="detail-meta"><span>创建人员：${esc(s.owner)}</span><span>创建时间：${s.createdAt}</span><span>问卷类型：${esc(s.type)}</span><span class="tag ${s.status}">${s.statusText}</span></div></div><div class="mini-stats"><div class="mini-stat">接收人员数<b>${s.total}</b></div><div class="mini-stat">已填写数<b>${s.done}</b></div><div class="mini-stat">待填写数<b>${pending}</b></div><div class="mini-stat">完成比例<b>${rate}%</b></div></div><section class="form-card"><div class="section-title">基础信息与发布设置</div><div class="detail-info-grid"><div><span>问卷名称</span><b>${esc(s.title)}</b></div><div><span>接收人员</span><b>${esc(s.target)}</b></div><div><span>填写周期</span><b>${esc(s.time)}</b></div><div><span>发布渠道</span><b>${s.type==='公开问卷'?'外部二维码':'系统定向'}</b></div><div><span>数据范围</span><b>${state.portal==='bureau'?'教育局组织内':'本学校内'}</b></div></div></section><section class="form-card readonly-questions"><div class="section-title">问卷题目 <span class="subtle">共 3 题</span></div>${surveyDetailQuestions(s)}</section>${s.done?`<section class="form-card"><div class="section-title">答卷明细（权限范围内）</div>${detailStats()}</section>`:''}`}
function filterOptions(items,value){return items.map(item=>{const pair=Array.isArray(item)?item:[item,item||'全部'];return `<option value="${pair[0]}" ${pair[0]===value?'selected':''}>${pair[1]}</option>`}).join('')}
function steps(){return `<div class="steps">${['基础信息','问卷设计','接收人员','发布设置'].map((x,i)=>`<div class="step ${state.step===i+1?'active':state.step>i+1?'done':''}"><span class="step-num">${state.step>i+1?'✓':i+1}</span>${x}</div>`).join('')}</div>`}
function createPage(){return `<a class="back-link" href="#list">← 返回问卷管理</a>${pageHead('创建问卷','完成问卷设计、对象选择与发布配置。','<button class="btn" data-action="save-draft">保存草稿</button>')} ${steps()} ${state.step===1?basicStep():state.step===2?editorStep():state.step===3?objectStep():publishStep()}`}
function createTemplatePage(){const routeId=state.page.startsWith('templates/edit/')?decodeURIComponent(state.page.split('/')[2]||''):'';if(routeId&&String(state.editingSurveyTemplateId)!==routeId){const item=surveyTemplateItems().find(x=>String(x.id)===routeId);if(!item)return `<a class="back-link" href="#templates">← 返回模板中心</a><div class="empty-state"><b>模板不存在</b><span>该模板已被删除或不属于当前端。</span></div>`;if(item.source==='system'){state.editingSurveyTemplateId=null;setTimeout(()=>{location.hash='templates';setTimeout(()=>toast('系统模板不可直接编辑，请使用参考新增'),0)},0);return `<a class="back-link" href="#templates">← 返回模板中心</a><div class="empty-state"><b>系统模板不可直接编辑</b><span>正在返回模板中心。</span></div>`}loadSurveyTemplateState(item,true)}const editing=Boolean(routeId),finalStep=publishStep().replace('data-action="publish">确认发布','data-action="save-template">保存模板');return `<a class="back-link" href="#templates">← 返回模板中心</a>${pageHead(editing?'编辑模板':'新增模板','设计模板的基础信息、问卷题目、接收人员和收集设置。')} ${steps()} ${state.step===1?basicStep():state.step===2?editorStep():state.step===3?objectStep():finalStep}`}
function basicStep(){return `<div class="basic-layout"><div class="form-card"><div class="section-title">基础信息</div><div class="form-grid"><div class="field full"><label class="required">问卷标题</label><input id="survey-title" type="text" maxlength="50" value="${esc(state.draftTitle)}" placeholder="请输入清晰、具体的问卷标题"></div><div class="field full"><label>问卷说明</label><textarea id="survey-description" maxlength="500" placeholder="说明调查目的、填写要求和数据用途">为全面了解教师数字化教学应用情况，请结合实际认真填写。本问卷数据仅用于教研分析。</textarea></div></div><div class="footer-actions"><button class="btn primary" data-action="next">下一步</button></div></div></div>`}
function defaultQuestions(){return [{type:'单选',title:'您目前主要任教的学段是？',required:true,options:['小学','初中','高中']},{type:'多选',title:'您在教学中使用过哪些数字化工具？',required:true,options:['智慧课堂','在线作业','AI备课','资源平台']},{type:'填空',title:'您希望获得哪些方面的培训支持？',required:false,options:[]}]}
function cloneQuestions(questions){return (questions||[]).map((q,index)=>({id:q.id||`q${index+1}`,type:q.type||'填空',title:q.title||`第 ${index+1} 题`,required:Boolean(q.required),options:[...(q.options||[])]}))}
function questionKind(type='填空'){const value=String(type).replace(/题$/,'');if(value.includes('单选'))return'single';if(value.includes('多选'))return'multiple';if(value.includes('日期'))return'date';if(value.includes('文件')||value.includes('图片'))return'file';if(value.includes('签名'))return'signature';if(value.includes('位置'))return'location';return'text'}
function questionTypeLabel(type){const kind=questionKind(type),labels={text:'填空题',single:'单选题',multiple:'多选题',date:'日期题',file:'文件/图片题',signature:'签名题',location:'位置题'};return labels[kind]}
function demoSurveyQuestions(s){const subject=String(s.title||'本问卷').replace(/调查|调研|问卷|征集/g,'').slice(0,18)||'本问卷',school=state.portal==='school';return cloneQuestions([{type:'填空',title:'请填写您的姓名',required:true,options:[]},{type:'单选',title:school?'您所属的年级是？':'您所在的学校是？',required:true,options:school?['七年级','八年级','九年级']:['实验学校','第一小学','第二中学','其他学校']},{type:'多选',title:`您认为“${subject}”应重点关注哪些方面？`,required:true,options:['数字化教学资源','教师培训与教研','校园安全服务','家校沟通服务']},{type:'日期',title:`请选择您参与“${subject}”的日期`,required:false,options:[]},{type:'文件/图片',title:`请上传与“${subject}”相关的文件或图片`,required:false,options:[]},{type:'签名',title:`请确认“${subject}”填写内容并签名`,required:true,options:[]},{type:'位置',title:`请选择您填写“${subject}”时所在的位置`,required:false,options:[]}])}
function surveyQuestions(s){if(!s)return[];if(!Array.isArray(s.questions))s.questions=demoSurveyQuestions(s);return s.questions}
function templateQuestionSchema(title,summary){const fields=String(summary||'').split('、').filter(Boolean);return cloneQuestions(fields.map((field,index)=>({type:index===1?'单选':'填空',title:field,required:index<2,options:index===1?['选项一','选项二']:[]})))}
const COMMON_QUESTIONS={phone:{title:'手机号',type:'填空',options:[]},gender:{title:'性别',type:'单选',options:['男','女']},idCard:{title:'身份证',type:'填空',options:[]},age:{title:'年龄',type:'填空',options:[]},className:{title:'所在班级',type:'填空',options:[]},department:{title:'所在部门',type:'填空',options:[]}};
function ensureTemplateStores(){if(SURVEY_TEMPLATE_STORE&&QUESTION_TEMPLATE_STORE)return;const surveySeeds={bureau:[['教师数字素养调研','工具应用、培训需求、意见建议'],['学校发展情况调查','办学条件、师资、发展困难'],['教育质量评价','课程实施、课堂质量、评价反馈'],['教师培训需求','学科、能力短板、培训形式'],['区域满意度调查','家长评价、社会意见、改进建议'],['校园安全专项检查','设施、制度、风险、整改情况']],school:[['通讯录收集','姓名、性别、手机号、微信号'],['班级作业收集','学生姓名、班级、作业附件'],['上下学交通调查','交通方式、接送人、位置'],['请假名单收集','学生姓名、日期、请假原因'],['新生报名登记','新生姓名、性别、证件信息'],['教师满意度调查','工作环境、管理评价、建议']]};const surveyDefaults={recipients:[],recipientTab:'',externalRecipient:false,frequency:'single',startDate:'2026-08-13',endDate:'2026-08-20',allowModify:true,dailyReminder:true,skipNonWorkday:false,reminderTime:'09:15'};SURVEY_TEMPLATE_STORE={bureau:surveySeeds.bureau.map(([title,summary],i)=>({id:`bureau-survey-system-${i+1}`,title,summary,questions:templateQuestionSchema(title,summary),creator:'系统',createdAt:`2026-08-${String(i+1).padStart(2,'0')} 09:00:00`,source:'system',...surveyDefaults})),school:surveySeeds.school.map(([title,summary],i)=>({id:`school-survey-system-${i+1}`,title,summary,questions:templateQuestionSchema(title,summary),creator:'系统',createdAt:`2026-08-${String(i+1).padStart(2,'0')} 09:00:00`,source:'system',...surveyDefaults}))};SURVEY_TEMPLATE_STORE.bureau.unshift({id:'bureau-survey-custom-1',title:'学期重点工作反馈',summary:'重点任务、完成进度、困难建议',questions:templateQuestionSchema('学期重点工作反馈','重点任务、完成进度、困难建议'),creator:'王明',createdAt:'2026-08-13 11:25:00',source:'custom',...surveyDefaults});SURVEY_TEMPLATE_STORE.school.unshift({id:'school-survey-custom-1',title:'班级情况周报',summary:'班级、出勤情况、本周事项',questions:templateQuestionSchema('班级情况周报','班级、出勤情况、本周事项'),creator:'陈芳',createdAt:'2026-08-13 15:40:00',source:'custom',...surveyDefaults});const systemQuestions=portal=>Object.entries(COMMON_QUESTIONS).map(([key,q],i)=>({id:`${portal}-question-system-${key}`,...q,required:false,source:'system',creator:'系统',createdAt:`2026-08-${String(i+1).padStart(2,'0')} 09:00:00`}));QUESTION_TEMPLATE_STORE={bureau:[...systemQuestions('bureau'),{id:'bureau-question-custom-1',title:'任教学段',type:'单选',required:true,options:['小学','初中','高中'],source:'custom',creator:'王明',createdAt:'2026-08-13 10:20:00'},{id:'bureau-question-custom-2',title:'培训需求方向',type:'多选',required:false,options:['数字工具应用','数据分析','人工智能辅助教学'],source:'custom',creator:'王明',createdAt:'2026-08-13 14:35:00'}],school:[...systemQuestions('school'),{id:'school-question-custom-1',title:'学生姓名',type:'填空',required:true,options:[],source:'custom',creator:'陈芳',createdAt:'2026-08-13 09:10:00'},{id:'school-question-custom-2',title:'所属年级',type:'单选',required:true,options:['七年级','八年级','九年级'],source:'custom',creator:'陈芳',createdAt:'2026-08-13 16:05:00'}]}}
function surveyTemplateItems(){ensureTemplateStores();return SURVEY_TEMPLATE_STORE[state.portal]}
function availableCommonQuestions(){ensureTemplateStores();return QUESTION_TEMPLATE_STORE[state.portal]}
function referenceTemplateTitle(title,items){const names=new Set(items.map(item=>item.title)),base=`${title}（副本）`;if(!names.has(base))return base;let index=2,candidate=`${title}（副本${index}）`;while(names.has(candidate)){index++;candidate=`${title}（副本${index}）`}return candidate}
function questionToolbox(){return `<aside class="toolbox"><div class="section-title">添加题目</div><details class="tool-group" open><summary>常用问题</summary><div class="tool-group-items">${availableCommonQuestions().map(q=>`<button class="tool-item" data-add-question-template="${q.id}">＋ ${esc(q.title)}</button>`).join('')}</div></details><details class="tool-group" open><summary>自定义问题</summary><div class="tool-group-items">${['填空','单选','多选','日期','文件/图片','签名','位置'].map(x=>`<button class="tool-item" data-add-type="${x}">＋ ${x}</button>`).join('')}</div></details></aside>`}
function questionPickerContent(){return `<div class="question-picker"><div class="question-picker-head"><h3>添加问题</h3><button class="picker-close" data-picker-close>×</button></div><details class="picker-group" open><summary>常用问题</summary><div class="picker-items">${availableCommonQuestions().map(q=>`<button class="picker-item" data-picker-template="${q.id}"><i></i>${esc(q.title)}</button>`).join('')}</div></details><details class="picker-group" open><summary>自定义问题</summary><div class="picker-items">${['填空','单选','多选','日期','文件/图片','签名','位置'].map(x=>`<button class="picker-item" data-picker-type="${x}"><i></i>${x}</button>`).join('')}</div></details></div>`}
function openQuestionPicker(){const m=$('#modal');m.innerHTML=questionPickerContent();m.classList.add('show','question-picker-mask');decorateOverlay($('.question-picker',m),'question-picker');const close=()=>{closePrd('route_change');m.classList.remove('show','question-picker-mask');m.innerHTML=''};m.querySelector('[data-picker-close]').onclick=close;m.querySelectorAll('[data-picker-template]').forEach(b=>b.onclick=()=>{addQuestionTemplate(b.dataset.pickerTemplate);close()});m.querySelectorAll('[data-picker-type]').forEach(b=>b.onclick=()=>{addCustomQuestion(b.dataset.pickerType);close()});m.onclick=e=>{if(e.target===m)close()}}
function canAddQuestion(){if(state.questions.length<100)return true;toast('单份问卷最多添加 100 道题');return false}
function addCommonQuestion(key){if(!canAddQuestion())return;const preset=COMMON_QUESTIONS[key];state.questions.push({...preset,required:false,options:[...preset.options]});state.selected=state.questions.length-1;renderShell()}
function addQuestionTemplate(id){if(!canAddQuestion())return;const preset=availableCommonQuestions().find(q=>String(q.id)===String(id));if(!preset)return;state.questions.push({title:preset.title,type:preset.type,required:Boolean(preset.required),options:[...(preset.options||[])]});state.selected=state.questions.length-1;renderShell()}
function addCustomQuestion(type){if(!canAddQuestion())return;state.questions.push({type,title:`请填写${type}题标题`,required:false,options:['选项一','选项二']});state.selected=state.questions.length-1;renderShell()}
function normalizedOptions(value){return String(value||'').split('\n').map(x=>x.trim()).filter(Boolean)}
function questionValidationError(title,type,options=[]){if(!title)return'请输入题目标题';if(title.length>200)return'题目标题不能超过 200 个字符';if(['单选','多选'].includes(type)){if(options.length<2)return'单选或多选题至少需要两个非空选项';if(options.length>20)return'单选或多选题最多设置 20 个选项';if(options.some(x=>x.length>50))return'每个选项不能超过 50 个字符'}return''}
function mobileAnswerValidationError(answers){if(!answers.name)return'请输入姓名';if(answers.name.length>20)return'姓名不能超过 20 个字符';if(!answers.gender)return'请选择性别';if(answers.wechat&&!/^[A-Za-z][A-Za-z0-9_-]{5,19}$/.test(answers.wechat))return'微信号须为 6～20 个字符，以字母开头且仅含字母、数字、下划线或连字符';if(answers.qq&&!/^\d{5,12}$/.test(answers.qq))return'QQ号须为 5～12 位数字';return''}
function editorStep(){return `<div class="editor">${questionToolbox()}<section class="question-list"><div class="section-title">问卷题目 <span class="subtle">共 ${state.questions.length} 题</span></div><div id="questions">${state.questions.map((q,i)=>questionCard(q,i)).join('')}</div><div class="footer-actions"><button class="btn" data-action="prev">上一步</button><button class="btn primary" data-action="next">下一步</button></div></section>${propertyPanel()}</div>`}
function questionCard(q,i){let mock=q.type==='单选'||q.type==='多选'?q.options.map(x=>`<div class="mock-option">${q.type==='单选'?'○':'□'} ${esc(x)}</div>`).join(''):`<div class="mock-input">${q.type==='日期'?'请选择日期':q.type==='文件/图片'?'点击上传文件':q.type==='签名'?'点击签名':q.type==='位置'?'点击获取位置':'请输入内容'}</div>`;return `<div class="question-card ${state.selected===i?'selected':''}" data-select-q="${i}"><div class="q-head"><div class="q-title"><span style="color:var(--green)">${String(i+1).padStart(2,'0')}.</span> ${esc(q.title)} ${q.required?'<span style="color:var(--danger)">*</span>':''}<div class="q-type">${q.type}</div></div><div class="q-actions"><button class="link-btn" data-q-action="up" data-i="${i}">↑</button><button class="link-btn" data-q-action="down" data-i="${i}">↓</button><button class="link-btn" data-q-action="copy" data-i="${i}">复制</button><button class="link-btn danger" data-q-action="delete" data-i="${i}">删除</button></div></div>${mock}</div>`}
function propertyPanel(){const q=state.questions[state.selected];if(!q)return'<aside class="property"><div class="empty">请选择题目</div></aside>';return `<aside class="property"><div class="section-title">题目设置</div><div class="field"><label>题目标题</label><textarea id="prop-title" maxlength="200">${esc(q.title)}</textarea></div><div class="field"><label>题目类型</label><select id="prop-type">${['填空','单选','多选','日期','文件/图片','签名','位置'].map(x=>`<option ${q.type===x?'selected':''}>${x}</option>`).join('')}</select></div><label class="inline-check"><input id="prop-required" type="checkbox" ${q.required?'checked':''}> 设为必答题</label>${['单选','多选'].includes(q.type)?`<div class="field" style="margin-top:14px"><label>选项（每行一个）</label><textarea id="prop-options" maxlength="1019">${q.options.join('\n')}</textarea><div class="hint">2～20 项，每项不超过 50 个字符。</div></div>`:''}<button class="btn primary" style="width:100%;margin-top:8px" data-action="apply-prop">应用修改</button></aside>`}
function recipientTabs(){return state.portal==='bureau'?[['department','部门'],['school','学校'],['external','其他']]:[['department','部门'],['parent','家长'],['class','班级']]}
function recipientTabMeta(){return state.portal==='bureau'?{department:['部门','选择教育局内部部门或下属人员'],school:['学校','选择学校管理员或默认职位，不向学生及家长发送'],external:['其他','通过填写二维码邀请外部人员']}:{department:['部门','选择学校内部部门或下属成员'],parent:['家长','按年级或班级选择学生家长'],class:['班级','按年级选择全部或部分班级']}}
function recipientExpanded(id,defaultOpen=true){return state.recipientExpansion.has(id)?state.recipientExpansion.get(id):defaultOpen}
function recipientCount(){return [...state.recipients.values()].reduce((sum,x)=>sum+x.count,0)}
function recipientSummary(){const names=[...state.recipients.values()].map(x=>x.name);if(state.externalRecipient)names.push('外部人员');return names.length>2?`${names.slice(0,2).join('、')}等 ${names.length} 项`:names.join('、')||'未选择'}
function recipientCheckbox(item,parentId=''){const selected=state.recipients.has(item.id)||(parentId&&state.recipients.has(parentId)),displayName=item.displayName||item.name;return `<label class="recipient-row" data-recipient-row data-name="${esc(displayName)}"><input type="checkbox" data-recipient-id="${item.id}" data-recipient-name="${esc(item.name)}" data-recipient-count="${item.count}" data-recipient-parent="${parentId}" ${selected?'checked':''}><span>${esc(displayName)}</span><em>${item.count} 人</em></label>`}
function treeRecipientContent(kind){return RECIPIENT_DATA[state.portal][kind].map(group=>{const open=recipientExpanded(group.id,true);return `<div class="recipient-group ${open?'expanded':''}" data-recipient-group data-name="${esc(group.name)}"><div class="recipient-parent-row"><button class="recipient-expander" data-toggle-recipient-node="${group.id}" aria-label="${open?'收起':'展开'}${esc(group.name)}">${open?'⌄':'›'}</button>${recipientCheckbox(group)}</div><div class="recipient-children ${open?'show':''}" data-recipient-children="${group.id}">${group.children.map(x=>recipientCheckbox({id:x[0],name:x[1],count:x[2]},group.id)).join('')}</div></div>`}).join('')}
function bureauSchoolContent(){const eligibleCount=SCHOOL_ROLES.reduce((sum,r)=>sum+r[2],0);return RECIPIENT_DATA.bureau.school.map(s=>{const full=state.recipients.has(s.id),open=recipientExpanded(s.id,false),school={...s,count:eligibleCount},roles=SCHOOL_ROLES.map((r,i)=>`${i===0||SCHOOL_ROLES[i-1][3]!==r[3]?`<div class="school-role-group-title">${r[3]}</div>`:''}${recipientCheckbox({id:`${s.id}-${r[0]}`,name:`${s.name}·${r[1]}`,displayName:r[1],count:r[2]},s.id)}`).join('');return `<div class="school-recipient ${open?'expanded':''}" data-school-card data-name="${esc(s.name)}" data-school-type="${s.type}"><div class="school-recipient-head"><button class="recipient-expander" data-toggle-recipient-node="${s.id}" aria-label="${open?'收起':'展开'}${esc(s.name)}">${open?'⌄':'›'}</button>${recipientCheckbox(school)}<span class="recipient-kind">${s.type}</span></div><div class="school-roles ${open?'show':''}" data-recipient-children="${s.id}">${roles}</div>${full?'<div class="hint">已选择该学校全部管理员及默认职位，不包含学生和家长。</div>':''}</div>`}).join('')}
function externalRecipientContent(){return `<div class="external-recipient"><div class="external-icon">↗</div><h3>其他外部人员</h3><p>发布成功后生成填写二维码，外部人员扫码填写。</p><label class="external-choice"><input type="checkbox" id="external-recipient" ${state.externalRecipient?'checked':''}> 将外部人员加入接收范围</label></div>`}
function recipientContent(){if(state.portal==='bureau'&&state.recipientTab==='school')return bureauSchoolContent();if(state.portal==='bureau'&&state.recipientTab==='external')return externalRecipientContent();return treeRecipientContent(state.recipientTab)}
function objectStep(){const tabs=recipientTabs();if(!tabs.some(x=>x[0]===state.recipientTab))state.recipientTab=tabs[0][0];const schoolFilter=state.portal==='bureau'&&state.recipientTab==='school',meta=recipientTabMeta()[state.recipientTab];return `<div class="form-card pc-recipient-card"><div class="section-title">选择接收人员</div><div class="pc-recipient-workspace"><nav class="recipient-side-nav"><div class="recipient-side-title">接收分类</div>${tabs.map(t=>`<button class="recipient-tab ${state.recipientTab===t[0]?'active':''}" data-recipient-tab="${t[0]}"><span>${t[1]}</span><em>›</em></button>`).join('')}</nav><section class="recipient-main-panel"><header class="recipient-panel-head"><div><h3>${meta[0]}</h3><p>${meta[1]}</p></div></header>${state.recipientTab!=='external'?`<div class="recipient-filter"><div class="recipient-search-box"><span>⌕</span><input id="recipient-search" type="text" value="${esc(state.recipientSearch)}" placeholder="搜索组织、学校或人员"></div>${schoolFilter?`<select id="school-type-filter" class="select"><option value="">全部学校类型</option>${['小学','初中','九年一贯制'].map(x=>`<option ${state.recipientSchoolType===x?'selected':''}>${x}</option>`).join('')}</select>`:''}</div><div class="recipient-table-head"><span>名称</span><span>${schoolFilter?'学校类型':'层级'}</span><span>人数</span></div>`:''}<div class="recipient-tree pc-recipient-tree">${recipientContent()}</div><div class="notice">系统将自动合并重复人员，并在发布时固化接收人员快照。</div></section><aside class="recipient-summary-panel"><div class="recipient-summary-head"><h3>已选范围</h3><span>${state.recipients.size+(state.externalRecipient?1:0)} 项</span></div><div id="selected-object-list" class="selected-object-list">${selectedObjectList()}</div><div class="recipient-summary-totals"><div class="summary-row"><span>预计参与人数</span><b>${recipientCount()}</b></div><div class="summary-row"><span>外部人员</span><b>${state.externalRecipient?'已包含':'未包含'}</b></div><div class="summary-row"><span>重复对象</span><b>0</b></div></div></aside></div><div class="footer-actions pc-recipient-actions"><button class="btn" data-action="prev">上一步</button><button class="btn primary" data-action="next">下一步</button></div></div>`}
function selectedObjectList(){const items=[...state.recipients.values()];return items.length||state.externalRecipient?`${items.map(x=>`<div class="chosen"><span>${esc(x.name)}<small>${x.count} 人</small></span><button class="link-btn danger" data-remove-recipient="${x.id}">×</button></div>`).join('')}${state.externalRecipient?'<div class="chosen"><span>外部人员<small>人数不限</small></span><button class="link-btn danger" data-remove-external>×</button></div>':''}`:'<div class="empty compact-empty">暂未选择接收人员</div>'}
function publishStep(){return `<div class="form-layout publish-layout"><div class="form-card"><div class="section-title">收集方式</div><div class="collection-options">${COLLECTION_FREQUENCIES.map(x=>`<label class="collection-option ${state.frequency===x.value?'active':''}"><input type="radio" name="frequency" value="${x.value}" data-frequency="${x.value}" ${state.frequency===x.value?'checked':''}><span><b>${x.label}</b><small>${x.description}</small></span></label>`).join('')}</div><div class="form-grid collection-grid"><div class="field"><label class="required">开始日期</label><input id="start-date" type="date" value="${state.startDate}"></div><div class="field"><label class="required">截止日期</label><input id="end-date" type="date" value="${state.endDate}"></div><div class="field full"><label>提交后修改</label><select id="allow-modify">${MODIFY_RULES.map(x=>`<option value="${x.value}" ${String(state.allowModify)===x.value?'selected':''}>${x.label}</option>`).join('')}</select></div>${state.frequency==='daily'?`<label class="setting-row full"><span><b>非工作日不收集</b><small>开启后周末及法定节假日不生成收集任务</small></span><input type="checkbox" id="skip-non-workday" ${state.skipNonWorkday?'checked':''}></label><label class="setting-row full"><span><b>每日收集提醒</b><small>每天按设置时间提醒未填写人员</small></span><input type="checkbox" id="daily-reminder" ${state.dailyReminder?'checked':''}></label>${state.dailyReminder?`<div class="field full"><label>提醒时间</label><input id="reminder-time" type="time" value="${state.reminderTime}"></div>`:''}`:''}</div><div class="notice">提交后修改仅更新所选原答卷，不会新增提交次数。</div><div class="footer-actions"><button class="btn" data-action="prev">上一步</button><button class="btn primary" data-action="publish">确认发布</button></div></div></div>`}
function recipientChildren(parentId){const source=state.portal==='bureau'&&parentId.startsWith('school-')?SCHOOL_ROLES.map(r=>({id:`${parentId}-${r[0]}`,name:`${RECIPIENT_DATA.bureau.school.find(s=>s.id===parentId)?.name||''}·${r[1]}`,count:r[2]})):[...Object.values(RECIPIENT_DATA[state.portal])].flat().filter(x=>x.children).find(x=>x.id===parentId)?.children.map(x=>({id:x[0],name:x[1],count:x[2]}))||[];return source}
function toggleRecipient(input){const id=input.dataset.recipientId,parent=input.dataset.recipientParent,name=input.dataset.recipientName,count=+input.dataset.recipientCount;if(!parent){recipientChildren(id).forEach(x=>state.recipients.delete(x.id));input.checked?state.recipients.set(id,{id,name,count,category:state.recipientTab,level:'group'}):state.recipients.delete(id)}else{const siblings=recipientChildren(parent);if(state.recipients.has(parent)){const group=state.recipients.get(parent);state.recipients.delete(parent);siblings.forEach(x=>{if(x.id!==id||input.checked)state.recipients.set(x.id,{...x,category:state.recipientTab,parent,level:'child'})})}else input.checked?state.recipients.set(id,{id,name,count,category:state.recipientTab,parent,level:'child'}):state.recipients.delete(id);if(siblings.length&&siblings.every(x=>state.recipients.has(x.id))){siblings.forEach(x=>state.recipients.delete(x.id));const parentInput=$(`[data-recipient-id="${parent}"]`);state.recipients.set(parent,{id:parent,name:parentInput?.dataset.recipientName||parent,count:+(parentInput?.dataset.recipientCount||siblings.reduce((n,x)=>n+x.count,0)),category:state.recipientTab,level:'group'})}}renderShell()}
function syncRecipientParents(){$$('[data-recipient-id]').forEach(input=>{const parent=input.dataset.recipientParent;if(!parent){const children=recipientChildren(input.dataset.recipientId),selected=children.filter(x=>state.recipients.has(x.id)).length;input.indeterminate=!state.recipients.has(input.dataset.recipientId)&&selected>0&&selected<children.length}})}
function applyRecipientFilter(){const keyword=$('#recipient-search')?.value.trim()||'',type=$('#school-type-filter')?.value||'';state.recipientSearch=keyword;state.recipientSchoolType=type;$$('[data-recipient-group]').forEach(group=>{const parentName=group.dataset.name||'',rows=$$('[data-recipient-row]',group),parentMatch=parentName.includes(keyword),childMatch=rows.some(row=>(row.dataset.name||'').includes(keyword));group.classList.toggle('hidden',Boolean(keyword)&&!parentMatch&&!childMatch);rows.forEach((row,i)=>row.classList.toggle('hidden',Boolean(keyword)&&i>0&&!parentMatch&&!(row.dataset.name||'').includes(keyword)));const children=$('.recipient-children',group);children?.classList.toggle('search-expanded',Boolean(keyword)&&childMatch)});$$('[data-school-card]').forEach(card=>{const typeMatch=!type||card.dataset.schoolType===type,nameMatch=!keyword||(card.textContent||'').includes(keyword);card.classList.toggle('hidden',!typeMatch||!nameMatch);$('[data-recipient-children]',card)?.classList.toggle('search-expanded',Boolean(keyword)&&nameMatch)});syncRecipientParents()}
function resetCreationState(){state.step=1;state.draftTitle='';state.questions=defaultQuestions();state.selected=0;state.recipients.clear();state.recipientTab='';state.recipientExpansion.clear();state.recipientSearch='';state.recipientSchoolType='';state.externalRecipient=false;state.frequency='single';state.startDate='2026-08-13';state.endDate='2026-08-20';state.allowModify=true;state.dailyReminder=true;state.skipNonWorkday=false;state.reminderTime='09:15';state.mobileSettingsSheet='';state.editingSurveyTemplateId=null}
function draftValidationError(){if(!state.draftTitle.trim())return'请输入问卷标题';if(state.draftTitle.trim().length>50)return'问卷标题不能超过 50 个字符';if(!state.questions.length)return'请至少添加一道题目';if(state.questions.length>100)return'单份问卷最多添加 100 道题';if(!state.recipients.size&&!state.externalRecipient)return'请至少选择一类接收人员';if(!state.startDate||!state.endDate)return'请选择开始日期和截止日期';if(state.startDate>state.endDate)return'开始日期不能晚于截止日期';if(state.frequency==='daily'&&state.dailyReminder&&!state.reminderTime)return'请选择每日提醒时间';return''}
function publishDraft(source='pc'){const error=draftValidationError();if(error){toast(error);return}const c=CONFIG[state.portal],id=Date.now(),external=state.externalRecipient,title=state.draftTitle||'新建问卷',target=recipientSummary(),total=recipientCount(),questions=cloneQuestions(state.questions),daily=state.frequency==='daily',time=daily?`每日 ${state.reminderTime||'09:15'}`:`${state.startDate.slice(5)} 至 ${state.endDate.slice(5)}`,finish=()=>{resetCreationState();if(source==='mobile')location.hash='mobile/templates';else{state.listView='published';location.hash='list'}renderShell();toast('问卷发布成功')};modal('确认发布问卷？',`系统将向已选接收人员发布“${esc(title)}”，发布后产生答卷即锁定题目结构。`,'确认发布',()=>{c.surveys.unshift({id,title,type:daily?'每日收集':external?'公开问卷':'系统定向',channel:external?'public':'internal',target,owner:currentUserName(),time,startDate:state.startDate,endDate:state.endDate,createdAt:formatSystemTime(),status:'running',statusText:'进行中',done:0,total,received:false,frequency:state.frequency,allowModify:state.allowModify,skipNonWorkday:daily?state.skipNonWorkday:false,dailyReminder:daily?state.dailyReminder:false,reminderTime:daily&&state.dailyReminder?state.reminderTime:'',questions});external?showExternalPublishResult(id,finish):finish()})}
function loadSurveyTemplateState(item,editing=false){resetCreationState();state.editingSurveyTemplateId=editing?item.id:null;state.draftTitle=item.title;state.questions=cloneQuestions(item.questions);state.selected=0;state.recipients=new Map((item.recipients||[]).map(([id,value])=>[id,{...value}]));state.recipientTab=item.recipientTab||'';state.externalRecipient=Boolean(item.externalRecipient);state.frequency=item.frequency||'single';state.startDate=item.startDate||'2026-08-13';state.endDate=item.endDate||'2026-08-20';state.allowModify=item.allowModify!==false;state.dailyReminder=item.dailyReminder!==false;state.skipNonWorkday=Boolean(item.skipNonWorkday);state.reminderTime=item.reminderTime||'09:15'}
function referenceSurveyTemplate(item){if(!item||item.source!=='system'){toast('仅系统模板支持参考新增');return}loadSurveyTemplateState(item,false);state.draftTitle=referenceTemplateTitle(item.title,surveyTemplateItems());state.step=1;location.hash='templates/create';renderShell();toast('已参考该问卷模板创建新模板，请完成编辑后保存')}
function surveyTemplateValue(existing){const title=state.draftTitle.trim(),summary=state.questions.map(q=>q.title).filter(Boolean).slice(0,4).join('、')||'暂无题目';return{id:existing?.id||`${state.portal}-survey-custom-${Date.now()}`,title,summary,questions:cloneQuestions(state.questions),creator:existing?.creator||currentUserName(),createdAt:existing?.createdAt||formatSystemTime(),source:existing?.source||'custom',recipients:[...state.recipients.entries()].map(([id,value])=>[id,{...value}]),recipientTab:state.recipientTab,externalRecipient:state.externalRecipient,frequency:state.frequency,startDate:state.startDate,endDate:state.endDate,allowModify:state.allowModify,dailyReminder:state.dailyReminder,skipNonWorkday:state.skipNonWorkday,reminderTime:state.reminderTime}}
function saveSurveyTemplate(){const list=surveyTemplateItems(),existing=list.find(x=>String(x.id)===String(state.editingSurveyTemplateId)),title=state.draftTitle.trim();if(existing?.source==='system'){state.editingSurveyTemplateId=null;location.hash='templates';renderShell();toast('系统模板不可直接编辑，请使用参考新增');return}if(!title){toast('请输入模板名称');state.step=1;renderShell();return}if(list.some(x=>x.title===title&&x!==existing)){toast('当前端已存在同名问卷模板');state.step=1;renderShell();return}const value=surveyTemplateValue(existing);if(existing)Object.assign(existing,value);else list.unshift(value);resetCreationState();state.templateTab='survey';location.hash='templates';renderShell();toast(existing?'问卷模板已更新':'问卷模板已创建')}
function deleteSurveyTemplate(id){const list=surveyTemplateItems(),item=list.find(x=>String(x.id)===String(id));if(!item)return;if(item.source==='system'){toast('系统模板不可删除');return}modal('删除问卷模板？',`删除“${esc(item.title)}”后无法恢复，已通过该模板创建的问卷不受影响。`,'确认删除',()=>{SURVEY_TEMPLATE_STORE[state.portal]=list.filter(x=>String(x.id)!==String(id));renderShell();toast('问卷模板已删除')})}
function externalQrPayload(s){const base=location.href?location.href.split('#')[0]:`${location.origin}${location.pathname}`;return `${base}#mobile/fill/${s.id}/external`}
function qrMatrix(value,size=25){let seed=2166136261,cells=Array(size*size).fill(false),reserved=Array(size*size).fill(false);for(const char of value){seed^=char.charCodeAt(0);seed=Math.imul(seed,16777619)>>>0}const set=(row,col,dark,lock=true)=>{if(row<0||col<0||row>=size||col>=size)return;cells[row*size+col]=dark;if(lock)reserved[row*size+col]=true},finder=(row,col)=>{for(let y=-1;y<=7;y++)for(let x=-1;x<=7;x++){const inside=x>=0&&x<=6&&y>=0&&y<=6,dark=inside&&(x===0||x===6||y===0||y===6||(x>=2&&x<=4&&y>=2&&y<=4));set(row+y,col+x,dark)}};finder(0,0);finder(0,size-7);finder(size-7,0);for(let i=8;i<size-8;i++){set(6,i,i%2===0);set(i,6,i%2===0)}set(size-8,8,true);for(let row=0;row<size;row++)for(let col=0;col<size;col++){const index=row*size+col;if(reserved[index])continue;seed=(Math.imul(seed,1664525)+1013904223)>>>0;cells[index]=Boolean((seed>>>30)^((row+col)%3===0))}return{size,cells}}
function qrMarkup(qr){return `<div class="demo-qr" style="--qr-size:${qr.size}" aria-label="问卷填写二维码">${qr.cells.map(dark=>`<i class="${dark?'on':''}"></i>`).join('')}</div>`}
function downloadQr(qr,filename){const unit=10,quiet=4,canvas=document.createElement('canvas'),size=(qr.size+quiet*2)*unit;canvas.width=size;canvas.height=size;const context=canvas.getContext('2d');context.fillStyle='#fff';context.fillRect(0,0,size,size);context.fillStyle='#182b3c';qr.cells.forEach((dark,index)=>{if(!dark)return;const row=Math.floor(index/qr.size),col=index%qr.size;context.fillRect((col+quiet)*unit,(row+quiet)*unit,unit,unit)});const save=url=>{const link=document.createElement('a');link.href=url;link.download=`${filename.replace(/[\\/:*?"<>|]/g,'_')}-二维码.png`;link.click();if(url.startsWith('blob:'))URL.revokeObjectURL(url)};canvas.toBlob?canvas.toBlob(blob=>blob&&save(URL.createObjectURL(blob))):save(canvas.toDataURL('image/png'))}
function qrScanPreviewMarkup(s){const available=s.status==='running';return `<div class="qr-scan-layer"><button class="qr-scan-close" data-close-qr-preview aria-label="关闭扫码实例">×</button><section class="qr-phone-shell"><header class="wechat-scan-head"><button data-close-qr-preview aria-label="返回">‹</button><b>问卷填写</b><span>•••</span></header><div class="qr-phone-screen">${available?mobileFormContent(s,false,true):`<div class="qr-scan-unavailable"><i>!</i><b>问卷${esc(s.statusText)}</b><span>当前问卷暂不可填写，请联系问卷发布人。</span></div>`}</div></section></div>`}
function openQrScanPreview(s,m){m.insertAdjacentHTML('beforeend',qrScanPreviewMarkup(s));const layer=$('.qr-scan-layer',m),close=()=>{closePrd('route_change');layer?.remove()};decorateOverlay($('.qr-phone-shell',layer),'qr-preview');$$('[data-close-qr-preview]',layer).forEach(button=>button.onclick=close);$('[data-qr-preview-submit]',layer)?.addEventListener('click',()=>toast('扫码实例提交成功（演示）'));layer.onclick=e=>{if(e.target===layer)close()}}
function openSurveyQr(s,finish=null,publishSuccess=false){const payload=externalQrPayload(s),qr=qrMatrix(payload),m=$('#modal'),available=s.status==='running',close=()=>{closePrd('route_change');m.classList.remove('show','qr-modal-mask','stats-confirm-mask');m.innerHTML=''};m.classList.remove('stats-confirm-mask');m.classList.add('qr-modal-mask');m.innerHTML=`<div class="modal external-result qr-result"><div class="qr-modal-head"><h3>${publishSuccess?'问卷发布成功':'问卷填写二维码'}</h3><button class="btn sm qr-demo-btn" id="open-scan-demo">扫码实例</button></div><p>${available?'外部人员可扫描二维码填写问卷。':'该问卷当前为“'+esc(s.statusText)+'”，二维码保留但暂不可提交。'}</p><div class="qr-survey-name">${esc(s.title)}</div>${qrMarkup(qr)}<div class="modal-actions"><button class="btn" id="download-survey-qr">下载二维码</button><button class="btn primary" id="finish-publish">${publishSuccess?'完成':'关闭'}</button></div></div>`;m.classList.add('show');decorateOverlay($('.qr-result',m),'qr');$('#open-scan-demo').onclick=()=>openQrScanPreview(s,m);$('#download-survey-qr').onclick=()=>{downloadQr(qr,s.title);toast('二维码已下载')};$('#finish-publish').onclick=()=>{close();finish&&finish()};m.onclick=e=>{if(e.target===m&&!publishSuccess)close()}}
function showExternalPublishResult(id,finish){const survey=CONFIG[state.portal].surveys.find(item=>item.id===id);openSurveyQr(survey,finish,true)}
function statsMobileMenuButton(s){return `<button class="stats-more-button" type="button" data-stats-more="${s.id}" aria-label="更多操作">...</button>`}
function openStatsActionSheet(s){const stage=$('.device-stage');if(!stage)return;$('.stats-action-mask',stage)?.remove();const m=document.createElement('div'),external=s.status!=='draft'&&s.channel!=='internal',statusActions=s.status==='running'?'<button type="button" data-sheet-action="pause">暂停</button><button type="button" class="danger" data-sheet-action="end">结束</button>':s.status==='paused'?'<button type="button" data-sheet-action="resume">恢复</button><button type="button" class="danger" data-sheet-action="end">结束</button>':'';m.className='stats-action-mask';m.innerHTML=`<section class="stats-action-sheet" role="dialog" aria-modal="true" aria-label="问卷操作"><header><h3>更多操作</h3><button type="button" class="stats-action-close" aria-label="关闭">×</button></header><div class="stats-action-list">${external?'<button type="button" data-sheet-action="qr">二维码</button>':''}${statusActions}<button type="button" class="danger" data-sheet-action="delete">删除</button></div><button type="button" class="stats-action-cancel">取消</button></section>`;stage.appendChild(m);const close=()=>m.remove();$('.stats-action-close',m).onclick=close;$('.stats-action-cancel',m).onclick=close;m.onclick=e=>{if(e.target===m)close()};$$('[data-sheet-action]',m).forEach(button=>button.onclick=()=>{const action=button.dataset.sheetAction;close();if(action==='qr'){openSurveyQr(s);return}if(action==='pause'||action==='resume'){const next=action==='pause'?['暂停问卷？','paused','已暂停']:['恢复问卷？','running','进行中'];modal(next[0],`操作后将立即更新“${esc(s.title)}”的填写状态。`,'确认',()=>{s.status=next[1];s.statusText=next[2];renderShell();toast('状态已更新')},'stats-confirm-mask');return}if(action==='end'){modal('提前结束问卷？',`结束后“${esc(s.title)}”将无法继续提交。`,'确认结束',()=>{s.status='ended';s.statusText='已结束';renderShell();toast('状态已更新')},'stats-confirm-mask');return}modal('删除问卷？',`删除“${esc(s.title)}”后，该问卷将从问卷管理、全部问卷和统计列表中移除。`,'确认删除',()=>{s.deleted=1;state.page='stats';location.hash='stats';renderShell();toast('问卷已删除')},'stats-confirm-mask')})}
function templateTabs(){return `<div class="tabs template-tabs"><button class="tab ${state.templateTab==='survey'?'active':''}" data-template-tab="survey">问卷模板</button><button class="tab ${state.templateTab==='question'?'active':''}" data-template-tab="question">问题模板</button></div>`}
function templatesPage(){return state.templateTab==='question'?questionTemplatesPage():surveyTemplatesPage()}
function surveyTemplatesPage(){const items=surveyTemplateItems();return `${pageHead('模板中心','', '<button class="btn primary" data-action="add-survey-template">+ 新增问卷模板</button>')}${templateTabs()}<div class="filter-card"><div class="toolbar filter-toolbar"><label class="filter-item"><span>模板名称：</span><input id="template-name" type="text" maxlength="50" placeholder="请输入模板名称"></label></div></div><div class="table-wrap template-table-wrap"><table class="data-table template-table"><thead><tr><th>序号</th><th>模板名称</th><th>模板内容</th><th>创建人</th><th>创建时间</th><th>操作</th></tr></thead><tbody>${items.map((x,i)=>`<tr data-template-name="${esc(x.title)}" data-survey-template-id="${esc(x.id)}"><td class="template-index">${i+1}</td><td><div class="title-cell">${esc(x.title)}</div></td><td>${esc(x.summary)}</td><td>${esc(x.creator)}</td><td class="nowrap">${esc(x.createdAt)}</td><td><div class="row-actions template-row-actions"><button class="link-btn" data-action="use-template" data-template-id="${esc(x.id)}">使用模板</button>${x.source==='system'?'<button class="link-btn" data-action="reference-survey-template">参考新增</button>':'<button class="link-btn" data-action="edit-survey-template">编辑</button><button class="link-btn danger" data-action="delete-survey-template">删除</button>'}</div></td></tr>`).join('')}</tbody></table></div>`}
function questionTemplatesPage(){const items=availableCommonQuestions();return `${pageHead('模板中心','', '<button class="btn primary" data-action="add-question-template">+ 新增问题模板</button>')}${templateTabs()}<div class="table-wrap template-table-wrap"><table class="data-table question-template-table"><thead><tr><th>序号</th><th>问题名称</th><th>问题类型</th><th>是否必答</th><th>选项/内容摘要</th><th>创建人</th><th>创建时间</th><th>操作</th></tr></thead><tbody>${items.map((q,i)=>`<tr data-question-template-id="${esc(q.id)}"><td>${i+1}</td><td><div class="title-cell">${esc(q.title)}</div></td><td>${esc(q.type)}</td><td>${q.required?'是':'否'}</td><td>${q.options?.length?esc(q.options.join('、')):'—'}</td><td>${esc(q.creator)}</td><td class="nowrap">${esc(q.createdAt)}</td><td><div class="row-actions template-row-actions">${q.source==='system'?'<button class="link-btn" data-action="reference-question-template">参考新增</button>':'<button class="link-btn" data-action="edit-question-template">编辑</button><button class="link-btn danger" data-action="delete-question-template">删除</button>'}</div></td></tr>`).join('')}</tbody></table></div>`}
function statsSurveys(){return CONFIG[state.portal].surveys.filter(s=>s.deleted!==1&&s.done>0)}
function statsSurvey(){const id=Number(state.page.split('/')[2]);return CONFIG[state.portal].surveys.find(s=>s.id===id)||statsSurveys()[0]}
function statsMobileHead(title,back='#stats',actions=''){return `<div class="stats-mobile-head"><a href="${back}" aria-label="返回">‹</a><b>${title}</b>${actions||'<i></i>'}</div>`}
function mobileTabs(active){return `<nav class="mobile-main-tabs"><a class="${active==='fill'?'active':''}" href="#mobile/fill">填写</a><a class="${active==='stats'?'active':''}" href="#stats">统计</a><a class="${active==='create'?'active':''}" href="#mobile/templates">新建</a></nav>`}
function mobileRoutePage(){const p=state.page.split('/');if(p[1]==='complete'&&p[2])return mobileCompletePage(+p[2]);if(p[1]==='fill'&&p[2])return mobileFormPage(+p[2],p[3]==='view');if(p[1]==='templates')return mobileTemplatesPage();if(p[1]==='create')return mobileCreatePage();if(p[1]==='settings')return mobileSettingsPage();if(p[1]==='recipients')return mobileRecipientsPage();return mobileFillListPage()}
function mobileReceived(){return CONFIG[state.portal].surveys.filter(s=>s.received&&s.deleted!==1)}
function mobileFillListPage(){let rows=mobileReceived();if(state.mobileFilter==='done')rows=rows.filter(s=>s.fillStatus==='submitted');if(state.mobileFilter==='todo')rows=rows.filter(s=>s.fillStatus!=='submitted');return `${statsMobileHead('填写','#dashboard')}${mobileTabs('fill')}<div class="mobile-filter">${[['all','全部'],['done','已填写'],['todo','未填写']].map(x=>`<button class="${state.mobileFilter===x[0]?'active':''}" data-mobile-filter="${x[0]}">${x[1]}</button>`).join('')}</div><div class="mobile-survey-list">${rows.map(s=>`<button class="mobile-survey-item" data-mobile-survey="${s.id}" data-mobile-view="${s.fillStatus==='submitted'?'view':'edit'}"><i class="${s.fillStatus==='submitted'?'done':'todo'}">${s.fillStatus==='submitted'?'✓':'✎'}</i><span><b>${esc(s.title)}</b><em>${s.fillStatus==='submitted'?'已填写':'请如实填写'}</em><small>发起人：${esc(s.owner)}</small></span><strong>›</strong></button>`).join('')}</div><div class="stats-list-end">没有更多了</div>`}
function mobileSurvey(id){return CONFIG[state.portal].surveys.find(s=>s.id===id)||mobileReceived()[0]}
function mobileFormContent(s,readonly=false,preview=false){const saved=state.mobileAnswers[s.id]||{},answers={name:saved.name||(readonly?'张三':''),gender:saved.gender||(readonly?'男':''),wechat:saved.wechat||(readonly?'A121312':''),qq:saved.qq||(readonly?'312345':'')};return `<div class="mobile-form-intro"><h1>${esc(s.title)}</h1><p>请如实填写</p></div><div class="mobile-question"><h3><b>01.</b> 姓名</h3><input data-mobile-answer="name" maxlength="20" value="${esc(answers.name)}" placeholder="请输入" ${readonly?'disabled':''}></div><div class="mobile-question"><h3><b>02.</b> 性别</h3>${['男','女'].map(x=>`<label><input type="radio" name="mobile-gender" value="${x}" ${answers.gender===x?'checked':''} ${readonly?'disabled':''}> ${x}</label>`).join('')}</div><div class="mobile-question"><h3><b>03.</b> 微信号</h3><input data-mobile-answer="wechat" maxlength="20" pattern="[A-Za-z][A-Za-z0-9_-]{5,19}" value="${esc(answers.wechat)}" placeholder="请输入" ${readonly?'disabled':''}></div><div class="mobile-question"><h3><b>04.</b> QQ号</h3><input data-mobile-answer="qq" maxlength="12" inputmode="numeric" pattern="[0-9]{5,12}" value="${esc(answers.qq)}" placeholder="请输入" ${readonly?'disabled':''}></div><div class="mobile-form-actions">${readonly?(s.allowModify?`<button class="outline" data-mobile-edit="${s.id}">修改</button>`:'')+`<a href="#stats/detail/${s.id}">查看此问卷统计 &gt;</a>`:preview?'<button data-qr-preview-submit>提交</button>':`<button data-action="mobile-submit" data-survey-id="${s.id}">提交</button>`}</div>`}
function mobileFormPage(id,view=false){const s=mobileSurvey(id),readonly=view&&s.fillStatus==='submitted';return `${statsMobileHead('填写','#mobile/fill')}${mobileFormContent(s,readonly)}`}
function mobileCompletePage(id){const s=mobileSurvey(id);return `${statsMobileHead('完成','#mobile/fill')}<section class="mobile-complete"><div class="mobile-complete-state"><i>✓</i><h1>上报已提交</h1><a href="#mobile/fill/${s.id}/view">查看提交</a></div></section>`}
function mobileTemplates(){return state.portal==='school'?[{title:'通讯录收集',fields:'姓名、性别',typeId:204},{title:'学院假期请假名单收集',fields:'学生姓名、学号',typeId:202},{title:'学生上下学交通方式收集',fields:'学生姓名、学生性别',typeId:203},{title:'班级作业收集',fields:'学生姓名、学号',typeId:201},{title:'新生报名登记收集',fields:'新生姓名、新生性别',typeId:202}]:[{title:'教师信息收集',fields:'姓名、任教学段',typeId:104},{title:'学校开学准备调查',fields:'学校名称、完成情况',typeId:102},{title:'教师培训需求',fields:'姓名、培训方向',typeId:101},{title:'校园安全专项检查',fields:'学校名称、检查结果',typeId:102},{title:'区域满意度调查',fields:'身份、评价',typeId:103}]}
function templatePreview(fields){return fields.split('、').map((x,i)=>`<div><b>${String(i+1).padStart(2,'0')}.</b>${x}<small>${i?'○ 选项一　○ 选项二':'请输入'}</small></div>`).join('')}
function mobileTemplatesPage(){const types=CONFIG[state.portal].surveyTypes;if(state.mobileTemplateType!=='all'&&!types.some(x=>String(x.id)===String(state.mobileTemplateType)))state.mobileTemplateType='all';const selected=types.find(x=>String(x.id)===String(state.mobileTemplateType)),items=mobileTemplates().filter(x=>state.mobileTemplateType==='all'||String(x.typeId)===String(state.mobileTemplateType)),options=[{id:'all',name:'全部问卷类型'},...types];return `${statsMobileHead('新建','#mobile/fill')}${mobileTabs('create')}<div class="mobile-template-category"><span>请选择新建分类</span><div class="mobile-template-picker"><button type="button" class="mobile-template-picker-toggle" data-mobile-template-type-toggle aria-haspopup="listbox" aria-expanded="${state.mobileTemplateTypeOpen}"><b>${esc(selected?.name||'全部问卷类型')}</b><i aria-hidden="true">▼</i></button>${state.mobileTemplateTypeOpen?`<div class="mobile-template-options" role="listbox" aria-label="问卷类型">${options.map(x=>{const active=String(state.mobileTemplateType)===String(x.id);return `<button type="button" role="option" aria-selected="${active}" class="${active?'active':''}" data-mobile-template-type="${x.id}"><span>${esc(x.name)}</span><b aria-hidden="true">${active?'✓':''}</b></button>`}).join('')}</div>`:''}</div></div><div class="mobile-template-grid"><button class="mobile-template-new" data-mobile-new><strong>＋</strong></button><h3>全新创建</h3>${items.length?items.map(x=>`<button class="mobile-template-card" data-mobile-template="${esc(x.title)}">${templatePreview(x.fields)}</button><h3>${esc(x.title)}</h3>`).join(''):`<div class="mobile-template-empty"><b>该类型暂无问卷模板</b><span>可使用“全新创建”自行设计问卷</span></div>`}</div><div class="stats-list-end">没有更多了</div>`}
function mobileCreatePage(){return `${statsMobileHead('创建问卷','#mobile/templates')}${mobileTabs('fill')}<section class="mobile-create-info"><input id="mobile-title" maxlength="50" value="${esc(state.draftTitle)}" placeholder="无标题上报表"><textarea id="mobile-description" maxlength="500" placeholder="点击添加填写描述"></textarea></section><button class="mobile-add-question" data-mobile-picker>＋ 添加问题</button>${state.questions.length?`<div class="mobile-created-questions">${state.questions.map((q,i)=>`<div><b>${String(i+1).padStart(2,'0')}.</b> ${esc(q.title)}<small>${q.type}</small></div>`).join('')}</div>`:''}<button class="mobile-next" data-action="mobile-next-settings">下一步</button>${state.mobileQuestionPicker?mobileQuestionSheet():''}`}
function mobileQuestionSheet(){return `<div class="mobile-sheet-mask"><section class="mobile-question-sheet"><button class="sheet-close" data-mobile-picker-close>×</button><h2>添加问题</h2><details open><summary>常用问题</summary>${Object.entries(COMMON_QUESTIONS).map(([k,q])=>`<button data-mobile-common="${k}">${q.title}</button>`).join('')}</details><details><summary>自定义问题</summary>${['填空','单选','多选','日期','文件/图片','签名','位置'].map(x=>`<button data-mobile-type="${x}">${x}</button>`).join('')}</details><button class="sheet-confirm" data-mobile-picker-confirm>确定</button></section></div>`}
function frequencyLabel(value=state.frequency){return COLLECTION_FREQUENCIES.find(x=>x.value===value)?.label||COLLECTION_FREQUENCIES[0].label}
function mobileSettingsChoiceSheet(){const frequency=state.mobileSettingsSheet==='frequency',options=frequency?COLLECTION_FREQUENCIES:MODIFY_RULES;return `<div class="mobile-sheet-mask" data-mobile-settings-close><section class="mobile-choice-sheet" role="dialog" aria-modal="true" aria-label="${frequency?'选择填写频次':'选择提交后修改规则'}"><header><h2>${frequency?'填写频次':'提交后修改'}</h2><button type="button" data-mobile-settings-close aria-label="关闭">×</button></header>${options.map(x=>{const active=frequency?state.frequency===x.value:String(state.allowModify)===x.value;return `<button type="button" class="mobile-choice-option ${active?'active':''}" ${frequency?`data-mobile-frequency="${x.value}"`:`data-mobile-modify="${x.value}"`}><span><b>${x.label}</b><small>${x.description}</small></span><i>${active?'✓':''}</i></button>`}).join('')}</section></div>`}
function mobileSettingsPage(){const selected=state.recipients.size+(state.externalRecipient?1:0),summary=selected?`${selected}项 · ${recipientCount()}人${state.externalRecipient?' · 含外部人员':''}`:'未选择';return `${statsMobileHead('问卷设置','#mobile/create')}<section class="mobile-settings"><button data-mobile-open-recipients><span>填写对象与范围</span><em>${summary}　›</em></button><button data-mobile-settings-sheet="frequency"><span>填写频次</span><em>${frequencyLabel()}　›</em></button><label class="mobile-settings-value"><span>开始日期</span><input id="mobile-start-date" type="date" value="${state.startDate}"></label><label class="mobile-settings-value"><span>截止日期</span><input id="mobile-end-date" type="date" value="${state.endDate}"></label><button data-mobile-settings-sheet="modify"><span>提交后修改</span><em>${state.allowModify?'截止前允许修改':'提交后不可修改'}　›</em></button>${state.frequency==='daily'?`<label><span>非工作日不开放</span><input type="checkbox" id="mobile-skip" ${state.skipNonWorkday?'checked':''}></label><label><span>每日填写提醒</span><input type="checkbox" id="mobile-remind" ${state.dailyReminder?'checked':''}></label>${state.dailyReminder?`<label class="mobile-settings-value"><span>提醒时间</span><input id="mobile-reminder-time" type="time" value="${state.reminderTime}"></label>`:''}`:''}<div class="mobile-settings-note">提交后修改仅更新所选原答卷，不会新增提交次数。</div></section><button class="mobile-next mobile-settings-confirm" data-action="mobile-publish">确定</button>${state.mobileSettingsSheet?mobileSettingsChoiceSheet():''}`}
function mobileRecipientTabs(){return state.portal==='bureau'?[['department','部门'],['school','学校'],['external','其他']]:[['department','部门'],['parent','家长'],['class','班级'],['external','其他']]}
function mobileRecipientGroups(){if(state.portal==='bureau'&&state.recipientTab==='school'){const count=SCHOOL_ROLES.reduce((sum,item)=>sum+item[2],0);return RECIPIENT_DATA.bureau.school.map(item=>({...item,count}))}return RECIPIENT_DATA[state.portal][state.recipientTab]||[]}
function mobileRecipientTree(){return mobileRecipientGroups().map(group=>{const open=recipientExpanded(group.id,false),children=recipientChildren(group.id),selected=state.recipients.has(group.id);return `<article class="mobile-recipient-group ${open?'open':''}" data-recipient-group data-name="${esc(group.name)}" ${group.type?`data-school-card data-school-type="${esc(group.type)}"`:''}><div class="mobile-recipient-row"><label data-recipient-row data-name="${esc(group.name)}"><input type="checkbox" data-recipient-id="${group.id}" data-recipient-name="${esc(group.name)}" data-recipient-count="${group.count}" ${selected?'checked':''}><span>${esc(group.name)}${group.type?`<small>${esc(group.type)}</small>`:''}</span></label>${children.length?`<button type="button" data-toggle-recipient-node="${group.id}">${open?'收起':'下级'}　›</button>`:''}</div>${children.length?`<div class="mobile-recipient-children recipient-children ${open?'show':''}" data-recipient-children="${group.id}">${children.map(child=>`<label class="mobile-recipient-child" data-recipient-row data-name="${esc(child.name)}"><input type="checkbox" data-recipient-id="${child.id}" data-recipient-parent="${group.id}" data-recipient-name="${esc(child.name)}" data-recipient-count="${child.count}" ${state.recipients.has(child.id)||selected?'checked':''}><span>${esc(child.name)}</span><em>${child.count}人</em></label>`).join('')}</div>`:''}</article>`}).join('')}
function mobileExternalRecipient(){return `<section class="mobile-recipient-external"><h3>外部人员填写</h3><p>开启后，问卷发布成功将生成填写二维码，外部人员可扫码填写。</p><label><span>允许外部人员填写</span><input type="checkbox" id="external-recipient" ${state.externalRecipient?'checked':''}></label></section>`}
function mobileRecipientsPage(){const tabs=mobileRecipientTabs();if(!tabs.some(x=>x[0]===state.recipientTab))state.recipientTab=tabs[0][0];const external=state.recipientTab==='external',groups=mobileRecipientGroups(),allSelected=groups.length&&groups.every(x=>state.recipients.has(x.id)),kind=recipientTabMeta()[state.recipientTab]?.[0]||'成员';return `${statsMobileHead('选择成员','#mobile/settings')}<section class="mobile-recipient-page"><nav class="mobile-recipient-tabs ${tabs.length===4?'four-tabs':''}">${tabs.map(tab=>`<button type="button" class="${state.recipientTab===tab[0]?'active':''}" data-recipient-tab="${tab[0]}">${tab[1]}</button>`).join('')}</nav>${external?mobileExternalRecipient():`<div class="mobile-recipient-search"><input id="recipient-search" value="${esc(state.recipientSearch)}" placeholder="请输入你要搜索的${kind}"></div>${state.portal==='bureau'&&state.recipientTab==='school'?`<select id="school-type-filter" class="mobile-school-filter"><option value="">全部学校类型</option>${['小学','初中','九年一贯制'].map(x=>`<option ${state.recipientSchoolType===x?'selected':''}>${x}</option>`).join('')}</select>`:''}<div class="mobile-recipient-breadcrumb">全部　›</div><label class="mobile-recipient-select-all"><input type="checkbox" data-mobile-recipient-all ${allSelected?'checked':''}><span>全选</span></label><div class="mobile-recipient-list">${mobileRecipientTree()}</div>`}</section><footer class="mobile-recipient-footer"><div><b>已选 ${state.recipients.size+(state.externalRecipient?1:0)} 项</b><span>预计 ${recipientCount()} 人${state.externalRecipient?' · 含外部人员':''}</span></div><a href="#mobile/settings">确定</a></footer>`}
function statsPage(){const rows=statsSurveys(),mobile=state.preview==='mobile';return `${statsMobileHead('教育问卷调研','#mobile/fill')}${mobileTabs('stats')}${pageHead(state.portal==='school'?'校内统计':'区域统计',mobile?'查看问卷提交进度、填写明细与题目数据。':'查看问卷提交进度、收集明细与题目数据。')}<div class="stats-list">${rows.map(s=>{const pending=s.total?Math.max(0,s.total-s.done):0;return `<article class="stats-survey-card" data-stats-open="${s.id}"><div><h3>${esc(s.title)}</h3><p>创建于${s.createdAt.slice(5,10).replace('-','月')}日</p></div><div class="stats-card-numbers"><button data-detail-kind="submitted" data-survey-id="${s.id}"><strong>${s.done}</strong><span>已提交</span></button><button class="pending" ${s.total?'':`disabled title="公开问卷无应收范围"`} data-detail-kind="pending" data-survey-id="${s.id}"><strong>${s.total?pending:'—'}</strong><span>${s.total?'未提交':mobile?'二维码填写':'公开收集'}</span></button></div></article>`}).join('')}</div><div class="stats-list-end">没有更多了</div>`}
function statsRoutePage(){const parts=state.page.split('/');if(parts[1]==='detail')return statsDetailPage();if(parts[1]==='people')return statsPeoplePage(parts[3]||'submitted');return statsPage()}
function normalizePendingStatsCards(){const s=state.page.startsWith('stats/detail/')?statsSurvey():null;$$('.stats-card-numbers .pending:disabled').forEach(card=>{card.title='外部人员无法统计未提交人数';$('span',card).textContent='未提交';$('strong',card).textContent='—'});if(!s||s.total>0)return;const grids=['.stats-summary-grid','.pc-summary-grid'];grids.forEach(selector=>{const grid=$(selector);if(!grid||$('.pending',grid))return;const card=document.createElement('button');card.className='pending untrackable';card.disabled=true;card.title='外部人员无法统计未提交人数';card.innerHTML='<span>未提交</span><strong>—</strong><em>外部人员无法统计</em>';const rate=$('.rate',grid);rate?grid.insertBefore(card,rate):grid.appendChild(card)})}
function statsDetailPage(){const s=statsSurvey(),pending=s.total?Math.max(0,s.total-s.done):0,rate=s.total?Math.round(s.done/s.total*100):null,back=state.statsBack||'#all-surveys',questions=statsQuestions(s);if(state.preview==='mobile')return `${statsMobileHead('统计详情',state.portal==='school'?'#stats':back,statsMobileMenuButton(s))}<div class="stats-detail-hero"><div><h2>${esc(s.title)}</h2><span class="tag ${s.status}">${s.statusText}</span></div><dl><div><dt>创建人</dt><dd>${esc(s.owner)}</dd></div><div><dt>创建时间</dt><dd>${s.createdAt.slice(0,10)}</dd></div><div><dt>统计范围</dt><dd>${esc(s.target)}</dd></div></dl></div><section class="stats-data"><h2>数据统计</h2><div class="stats-summary-grid"><button class="submitted" data-detail-kind="submitted" data-survey-id="${s.id}"><strong>${s.done}</strong><span>已提交</span><em>查看明细</em></button>${s.total?`<button class="pending" data-detail-kind="pending" data-survey-id="${s.id}"><strong>${pending}</strong><span>未提交</span><em>查看明细</em></button>`:''}${rate===null?'':`<div class="rate stats-summary-rate"><strong>${rate}%</strong><span>完成率</span><em>已提交人数 / 应提交人数</em></div>`}</div></section><section class="question-analytics"><h2>题目数据</h2>${questions.map((q,i)=>questionStatRow(q,i,s.id)).join('')}</section>`;const selected=Math.min(state.pcStatsQuestion,questions.length-1),q=questions[selected];return `<div class="pc-stats-page"><div class="pc-stats-breadcrumb"><a class="pc-back-btn" href="${back}">← 返回</a><span>问卷统计</span></div><header class="pc-stats-header"><div><div class="pc-stats-title"><h1>${esc(s.title)}</h1><span class="tag ${s.status}">${s.statusText}</span></div><dl><div><dt>创建人</dt><dd>${esc(s.owner)}</dd></div><div><dt>创建时间</dt><dd>${s.createdAt.slice(0,10)}</dd></div></dl></div></header><section class="pc-stats-summary"><div class="pc-section-head"><div><h2>数据统计</h2><p>查看问卷提交进度与人员明细</p></div></div><div class="pc-summary-grid"><button class="submitted" data-detail-kind="submitted" data-survey-id="${s.id}"><span>已提交</span><strong>${s.done}</strong><em>查看已提交明细 →</em></button>${s.total?`<button class="pending" data-detail-kind="pending" data-survey-id="${s.id}"><span>未提交</span><strong>${pending}</strong><em>查看未提交明细 →</em></button>`:''}${rate===null?'':`<div class="rate"><span>完成率</span><strong>${rate}%</strong><em>已提交人数 / 应提交人数</em></div>`}</div></section><section class="pc-question-section"><div class="pc-section-head"><div><h2>题目数据</h2><p>共 ${questions.length} 道题，点击左侧题目切换统计结果</p></div></div><div class="pc-question-layout"><nav class="pc-question-nav">${questions.map((item,i)=>`<button class="${selected===i?'active':''}" data-pc-question-index="${i}"><b>${String(i+1).padStart(2,'0')}</b><span>${esc(item.title)}<small>${item.type}</small></span><em>${item.count} 份</em></button>`).join('')}</nav><article class="pc-question-detail"><div class="pc-question-detail-head"><div><span>第 ${selected+1} 题 · ${q.type}</span><h3>${esc(q.title)}</h3></div><strong>${q.count}<small>有效回答</small></strong></div>${questionStatBody(q,s.id,selected)}</article></div></section></div>`}
function completeTextAnswers(count,base,templates,isName=false){if(!count)return[];return Array.from({length:count},(_,i)=>{if(i<base.length)return base[i];const value=templates[(i-base.length)%templates.length];return isName?`${value}${i>=base.length+templates.length?String(Math.floor((i-base.length)/templates.length)+1).padStart(2,'0'):''}`:`${value}（第 ${i+1} 条）`})}
function distributedOptions(count,labels,weights){let remaining=count;return labels.map((label,i)=>{const value=i===labels.length-1?remaining:Math.min(remaining,Math.round(count*weights[i]));remaining-=value;return[label,value]})}
function demoRecords(count,templates){return Array.from({length:Math.min(count,8)},(_,i)=>({...templates[i%templates.length],submitter:['张雨晴','李文博','周老师','王晨曦','陈思源','赵雨桐','刘子涵','孙嘉宁'][i%8],time:`2026-08-${String(13-i%5).padStart(2,'0')} ${String(9+i).padStart(2,'0')}:${String(8+i*7).padStart(2,'0')}`}))}
function statsQuestionFromSchema(s,source,index){const total=s.done,kind=questionKind(source.type),base={title:source.title,type:questionTypeLabel(source.type),kind,count:total},school=state.portal==='school';if(kind==='text')return{...base,answers:completeTextAnswers(total,['张雨晴','李文博','周老师'],['王晨曦','陈思源','赵雨桐','刘子涵','孙嘉宁','吴老师','郑文轩','林晓月'],source.title.includes('姓名'))};if(kind==='single'){const labels=source.options?.length?source.options:(school?['七年级','八年级','九年级']:['实验学校','第一小学','第二中学','其他学校']),weights=labels.map((_,i)=>i===labels.length-1?1:Math.max(.08,(labels.length-i)/(labels.length*(labels.length+1)/2)));return{...base,options:distributedOptions(total,labels,weights)}}if(kind==='multiple'){const valid=Math.max(0,Math.round(total*.94)),labels=source.options?.length?source.options:['选项一','选项二','选项三'];return{...base,count:valid,options:labels.map((label,i)=>[label,Math.round(valid*Math.max(.2,.72-i*.14))])}}if(kind==='date'){const valid=Math.max(0,Math.round(total*.86));return{...base,count:valid,dates:distributedOptions(valid,['2026-08-17','2026-08-18','2026-08-19','2026-08-20'],[.34,.29,.22,.15])}}if(kind==='file'){const valid=Math.max(0,Math.round(total*.56));return{...base,count:valid,files:demoRecords(valid,[{name:'校园环境照片.jpg',format:'JPG',size:'2.4 MB',preview:'image'},{name:'情况说明.pdf',format:'PDF',size:'860 KB',preview:'file'},{name:'活动现场.png',format:'PNG',size:'1.8 MB',preview:'image'},{name:'信息汇总表.xlsx',format:'XLSX',size:'128 KB',preview:'sheet'}])}}if(kind==='signature'){const valid=Math.max(0,Math.round(total*.81));return{...base,count:valid,signatures:demoRecords(valid,[{name:'张雨晴'},{name:'李文博'},{name:'周老师'},{name:'王晨曦'}])}}if(kind==='location'){const valid=Math.max(0,Math.round(total*.77)),labels=school?['学校东门','教学楼','体育场','学生宿舍']:['教育局机关','临江县实验学校','临江县第一小学','临江县第二中学'],addresses=school?['临江县育才路18号东门','临江县育才路18号教学区','临江县育才路18号运动区','临江县育才路18号生活区']:['临江县行政中心教育局办公区','临江县学府路16号','临江县朝阳路8号','临江县青年路25号'];return{...base,count:valid,locations:distributedOptions(valid,labels,[.38,.27,.21,.14]).map((item,i)=>({name:item[0],count:item[1],address:addresses[i],coordinate:[['30.2741','120.1551'],['30.2816','120.1628'],['30.2684','120.1495'],['30.2892','120.1713']][i]}))}}return base}
function statsQuestions(s){return surveyQuestions(s).map((question,index)=>statsQuestionFromSchema(s,question,index))}
function textAnswerKey(surveyId,questionIndex){return `${state.portal}:${surveyId}:${questionIndex}`}
function textAnswerRows(answers,start=0){return answers.map((answer,i)=>`<div class="text-answer-row"><b>${String(start+i+1).padStart(2,'0')}</b><span>${esc(answer)}</span></div>`).join('')}
function optionStatRows(q,label='份'){if(!q.count)return '<div class="text-answer-empty">暂无有效回答</div>';return q.options.map(x=>{const pct=Math.round(x[1]/q.count*100);return `<div class="option-stat"><span>${esc(x[0])}</span><div><i style="width:${Math.min(100,pct)}%"></i></div><b>${x[1]}${label} · ${pct}%</b></div>`}).join('')}
function textQuestionStat(q,surveyId,questionIndex){if(!q.count)return '<div class="text-answer-empty">暂无文本回答</div>';const key=textAnswerKey(surveyId,questionIndex),view=state.textAnswerViews[key]||{expanded:false,page:1};if(!view.expanded)return `<div class="text-answers"><div class="text-answer-list preview">${textAnswerRows(q.answers.slice(0,3))}</div>${q.count>3?`<button class="link-btn" data-action="view-all-answers" data-answer-key="${key}">查看全部 ${q.count} 条回答</button>`:''}</div>`;const pageSize=10,totalPages=Math.max(1,Math.ceil(q.count/pageSize)),page=Math.min(Math.max(1,view.page||1),totalPages),start=(page-1)*pageSize,rows=q.answers.slice(start,start+pageSize);return `<div class="text-answers expanded"><div class="text-answer-toolbar"><span>全部回答（${q.count}）</span><button class="link-btn" data-action="collapse-all-answers" data-answer-key="${key}">收起回答</button></div><div class="text-answer-list">${textAnswerRows(rows,start)}</div><div class="text-answer-pagination"><button class="btn sm" data-action="page-text-answers" data-answer-key="${key}" data-answer-page="${page-1}" ${page===1?'disabled':''}>上一页</button><span>第 ${page} / ${totalPages} 页</span><button class="btn sm" data-action="page-text-answers" data-answer-key="${key}" data-answer-page="${page+1}" ${page===totalPages?'disabled':''}>下一页</button></div></div>`}
function dateQuestionStat(q){if(!q.count)return '<div class="text-answer-empty">暂无日期回答</div>';return `<div class="stat-caption">按日期汇总 · 共 ${q.count} 份有效回答</div><div class="date-stat-list">${q.dates.map(x=>{const pct=Math.round(x[1]/q.count*100);return `<div class="date-stat"><time>${x[0]}</time><div><i style="width:${pct}%"></i></div><b>${x[1]}份 · ${pct}%</b></div>`}).join('')}</div>`}
function statPreviewAttrs(kind,title,submitter,time){return `data-stat-preview="${kind}" data-preview-title="${esc(title)}" data-preview-submitter="${esc(submitter)}" data-preview-time="${esc(time)}"`}
function fileQuestionStat(q){if(!q.count)return '<div class="text-answer-empty">暂无上传的文件或图片</div>';return `<div class="stat-caption">最近上传记录（共 ${q.count} 份）</div><div class="asset-stat-grid">${q.files.map(x=>{const preview=x.preview==='image',attrs=preview?statPreviewAttrs('image',x.name,x.submitter,x.time):'';return `<article class="asset-stat-card">${preview?`<button type="button" class="asset-preview image" ${attrs}><span>图片预览</span></button>`:`<div class="asset-preview ${x.preview}"><span>${x.format}</span></div>`}<div><b>${esc(x.name)}</b><span>${x.format} · ${x.size}</span><small>${esc(x.submitter)} · ${x.time}</small><button class="link-btn" ${preview?attrs:'data-preview-stat-asset="文件"'}>查看</button></div></article>`}).join('')}</div>`}
function signatureQuestionStat(q){if(!q.count)return '<div class="text-answer-empty">暂无签名记录</div>';return `<div class="stat-caption">最近签名记录（共 ${q.count} 份）</div><div class="signature-stat-grid">${q.signatures.map(x=>{const attrs=statPreviewAttrs('signature',x.name,x.submitter,x.time);return `<article class="signature-stat-card"><button type="button" class="signature-preview" ${attrs}>${esc(x.name)}</button><b>${esc(x.submitter)}</b><span>${x.time}</span><button class="link-btn" ${attrs}>预览签名</button></article>`}).join('')}</div>`}
function locationQuestionStat(q){if(!q.count)return '<div class="text-answer-empty">暂无位置数据</div>';return `<div class="location-stat-list">${q.locations.map(x=>`<article><b>${esc(x.name)}</b><strong>${x.count}人</strong><span>${esc(x.address)}</span><small>坐标 ${x.coordinate[0]}, ${x.coordinate[1]}</small></article>`).join('')}</div>`}
function openStatPreview(trigger){const kind=trigger.dataset.statPreview,title=trigger.dataset.previewTitle||'',submitter=trigger.dataset.previewSubmitter||'',time=trigger.dataset.previewTime||'',m=$('#modal'),visual=kind==='image'?`<div class="asset-preview image stat-preview-image"><span>${esc(title)}</span></div>`:`<div class="stat-preview-signature">${esc(title)}</div>`;m.innerHTML=`<div class="modal stat-preview-modal"><div class="stat-preview-head"><h3>${kind==='image'?'图片内容':'签字内容'}</h3><button type="button" class="stat-preview-close" aria-label="关闭">×</button></div>${visual}<div class="stat-preview-meta"><b>${esc(title)}</b><span>${esc(submitter)} · ${esc(time)}</span></div></div>`;m.classList.add('show');const close=()=>{m.classList.remove('show');m.innerHTML=''};$('.stat-preview-close',m).onclick=close;m.onclick=e=>{if(e.target===m)close()}}
function questionStatBody(q,surveyId,questionIndex){if(q.kind==='text')return textQuestionStat(q,surveyId,questionIndex);if(q.kind==='single')return optionStatRows(q);if(q.kind==='multiple')return `<div class="stat-caption">选择次数 / 选择率（多选题合计选择率允许超过 100%）</div>${optionStatRows(q,'次')}`;if(q.kind==='date')return dateQuestionStat(q);if(q.kind==='file')return fileQuestionStat(q);if(q.kind==='signature')return signatureQuestionStat(q);if(q.kind==='location')return locationQuestionStat(q);return '<div class="text-answer-empty">暂无可展示的统计数据</div>'}
function questionStatRow(q,i,surveyId){const open=state.openQuestion===i;return `<article class="question-stat ${open?'open':''}"><button class="question-stat-head" data-question-index="${i}"><span><b>${String(i+1).padStart(2,'0')}.</b> ${q.title}<small>${q.type}</small></span><em>${q.count}份⌄</em></button>${open?`<div class="question-stat-body">${questionStatBody(q,surveyId,i)}</div>`:''}</article>`}
function statsPeopleSeeds(kind){const school=state.portal==='school';if(kind==='submitted')return school?[{name:'张雨晴',scope:'七年级1班',scopeType:'class',identity:'学生',mobile:'13800138001'},{name:'李文博',scope:'七年级2班',scopeType:'class',identity:'学生',mobile:'13800138002'},{name:'周老师',scope:'数学组',scopeType:'department',identity:'教职工',mobile:'13800138003'},{name:'王晨曦',scope:'八年级3班',scopeType:'class',identity:'学生',mobile:'13800138004'},{name:'陈思源',scope:'九年级1班',scopeType:'class',identity:'学生',mobile:'13800138005'}]:[{name:'张雨晴',scope:'临江县实验学校',scopeType:'school',identity:'教师',mobile:'13800138001'},{name:'李文博',scope:'临江县第一小学',scopeType:'school',identity:'教师',mobile:'13800138002'},{name:'周老师',scope:'临江县第二中学',scopeType:'school',identity:'教师',mobile:'13800138003'},{name:'王晨曦',scope:'城关小学',scopeType:'school',identity:'管理人员',mobile:'13800138004'},{name:'陈思源',scope:'民族中学',scopeType:'school',identity:'教师',mobile:'13800138005'}];return school?[{name:'孙老师',scope:'语文组',scopeType:'department',identity:'教职工',mobile:'13900139001'},{name:'赵同学',scope:'七年级3班',scopeType:'class',identity:'学生',mobile:'13900139002'},{name:'钱同学',scope:'八年级1班',scopeType:'class',identity:'学生',mobile:'13900139003'},{name:'周老师',scope:'教务处',scopeType:'department',identity:'教职工',mobile:'13900139004'}]:[{name:'孙老师',scope:'办公室',scopeType:'department',identity:'内部人员',mobile:'13900139001'},{name:'赵老师',scope:'临江县实验学校',scopeType:'school',identity:'学校人员',mobile:'13900139002'},{name:'钱老师',scope:'临江县第一小学',scopeType:'school',identity:'学校人员',mobile:'13900139003'},{name:'周老师',scope:'教研室',scopeType:'department',identity:'内部人员',mobile:'13900139004'}]}
function statsAnswerValues(questions,person,index){return questions.map(q=>{if(q.kind==='text')return person.name;if(q.kind==='single')return q.options.length?q.options[index%q.options.length][0]:'';if(q.kind==='multiple')return q.options.slice(0,Math.min(q.options.length,index%3+1)).map(x=>x[0]).join('、');if(q.kind==='date')return q.dates.length?q.dates[index%q.dates.length][0]:'';if(q.kind==='file')return q.files.length?q.files[index%q.files.length].name:'未上传';if(q.kind==='signature')return `已签名（${person.name}）`;if(q.kind==='location'){const x=q.locations[index%Math.max(1,q.locations.length)];return x?`${x.name}｜${x.address}｜${x.coordinate[0]}, ${x.coordinate[1]}`:''}return''})}
function storedResponseValues(questions,record,fallback){if(!record?.answers?.length)return fallback;return questions.map((q,index)=>{const exact=record.answers.find(answer=>answer[0]===q.title);return String(exact?.[1]??record.answers[index]?.[1]??fallback[index]??'')})}
function statsPeopleData(kind,s=statsSurvey(),full=false){const seeds=statsPeopleSeeds(kind),target=kind==='submitted'?s.done:Math.max(0,s.total-s.done),length=full?target:Math.min(target,seeds.length),questions=kind==='submitted'?statsQuestions(s):null,records=kind==='submitted'?(MY_RESPONSES[state.portal]?.[s.id]||[]):[];return Array.from({length},(_,index)=>{const seed=seeds[index%seeds.length],round=Math.floor(index/seeds.length),person={...seed,name:round?`${seed.name}${round+1}`:seed.name,mobile:round?`13${String(800000000+index).slice(-9)}`:seed.mobile};if(kind==='submitted'){const record=records[index],fallback=statsAnswerValues(questions,person,index);person.responseId=record?.id||`${String(s.id).toUpperCase()}-${String(index+1).padStart(6,'0')}`;person.submittedAt=record?.submittedAt||`2026-08-${String(13-index%6).padStart(2,'0')} ${String(8+index%10).padStart(2,'0')}:${String(index*7%60).padStart(2,'0')}:${String(index*11%60).padStart(2,'0')}`;person.status='已提交';person.answers=storedResponseValues(questions,record,fallback)}return person})}
function exportStatsWorkbook(kind,s=statsSurvey()){try{if(!window.XLSX)throw new Error('XLSX library unavailable');const people=statsPeopleData(kind,s,true),isDone=kind==='submitted';if(!people.length)return toast('暂无可下载的明细');let rows;if(isDone){const questions=statsQuestions(s);rows=people.map((person,rowIndex)=>{const row={'序号':rowIndex+1,'姓名':String(person.name),'所属范围':String(person.scope),'身份':String(person.identity),'手机号':String(person.mobile),'提交时间':String(person.submittedAt),'提交状态':String(person.status)};questions.forEach((q,index)=>row[`第${String(index+1).padStart(2,'0')}题：${q.title}`]=String(person.answers[index]??''));return row})}else{const scopeTitle=state.portal==='school'?'部门/班级':'部门/学校';rows=people.map(person=>({'姓名':String(person.name),[scopeTitle]:String(person.scope),'手机号':String(person.mobile)}))}const sheet=XLSX.utils.json_to_sheet(rows),book=XLSX.utils.book_new();sheet['!cols']=isDone?[{wch:8},{wch:14},{wch:22},{wch:12},{wch:15},{wch:21},{wch:12},...statsQuestions(s).map(q=>({wch:q.kind==='location'?46:q.kind==='multiple'?32:24}))]:[{wch:14},{wch:24},{wch:15}];XLSX.utils.book_append_sheet(book,sheet,isDone?'已提交明细':'未提交明细');XLSX.writeFile(book,isDone?'下载已提交明细.xlsx':'下载未提交明细.xlsx',{compression:true});toast(`${isDone?'已提交':'未提交'}明细下载成功`)}catch(error){console.error(error);toast('明细下载失败，请重试')}}
function statsPeoplePage(kind){const s=statsSurvey(),isDone=kind==='submitted',trackable=isDone||s.total>0,count=isDone?s.done:trackable?Math.max(0,s.total-s.done):null,rows=trackable?statsPeopleData(kind,s):[],school=state.portal==='school',back=`#stats/detail/${s.id}`,pendingHead=school?'部门/班级':'部门/学校',listHead=`<div class="people-list-head ${isDone?'':'pending'}"><b>姓名</b><b>${isDone?(school?'班级/部门':'学校'):pendingHead}</b><b>手机号</b></div>`,listRows=rows.length?rows.map(x=>`<div class="people-row ${isDone?'':'pending'}" data-scope-type="${x.scopeType}"><span><b>${esc(x.name)}</b></span><span>${esc(x.scope)}</span><span>${esc(x.mobile)}</span></div>`).join(''):`<div class="pending-empty"><b>${trackable?'暂无未提交人员':'外部人员无法识别未提交名单'}</b><span>${trackable?'当前所有可识别接收人员均已提交。':'二维码填写不预先绑定人员身份，因此无法生成未提交名单。'}</span></div>`,download=trackable?`<button class="stats-download" data-action="download-stats" data-stats-kind="${kind}">下载${isDone?'已提交':'未提交'}明细</button>`:'',content=`<section class="people-overview"><div class="people-donut ${trackable?'':'untrackable'}"><span>全部<b>${count===null?'—':count}</b></span></div></section><section class="people-list ${isDone?'':'pending-people-list'}">${listHead}${listRows}${download}</section>`;if(state.preview==='mobile')return `${statsMobileHead('填写明细',back)}${content}`;return `<div class="pc-stats-page pc-people-page"><div class="pc-stats-breadcrumb"><a class="pc-back-btn" href="${back}">← 返回问卷统计</a><span>收集明细</span></div><header class="pc-people-header"><div><h1>${isDone?'已提交':'未提交'}明细</h1><p>${esc(s.title)}</p></div>${trackable?`<button class="btn primary" data-action="download-stats" data-stats-kind="${kind}">下载${isDone?'已提交':'未提交'}明细</button>`:'<span class="subtle">外部人员无法统计</span>'}</header><div class="pc-people-layout">${content}</div></div>`}
