function openSurveyTypeModal(item){const editing=Boolean(item),m=$('#modal');m.innerHTML=`<div class="modal"><h3>${editing?'编辑':'新增'}问卷类型</h3><div class="field"><label class="required">类型名称</label><input id="survey-type-name" type="text" maxlength="20" value="${esc(item?.name||'')}" placeholder="请输入类型名称"></div><div class="field" style="margin-top:16px"><label>类型说明</label><textarea id="survey-type-description" maxlength="100" placeholder="请输入类型适用范围或用途">${esc(item?.description||'')}</textarea><div class="hint">名称不超过 20 个字符，说明不超过 100 个字符。</div></div><div class="modal-error" id="survey-type-error"></div><div class="modal-actions"><button class="btn" id="cancel-modal">取消</button><button class="btn primary" id="save-survey-type">保存</button></div></div>`;m.classList.add('show');$('#survey-type-name').focus();$('#cancel-modal').onclick=()=>m.classList.remove('show');$('#save-survey-type').onclick=()=>{const name=$('#survey-type-name').value.trim(),description=$('#survey-type-description').value.trim(),duplicate=CONFIG[state.portal].surveyTypes.some(x=>x.name===name&&x.id!==item?.id);if(!name){$('#survey-type-error').textContent='请输入类型名称';return}if(duplicate){$('#survey-type-error').textContent='当前组织已存在同名问卷类型';return}if(editing){item.name=name;item.description=description}else CONFIG[state.portal].surveyTypes.unshift({id:Date.now(),name,description,surveyCount:0,creator:currentUserName(),createdAt:formatSystemTime()});m.classList.remove('show');renderShell();toast(`问卷类型已${editing?'更新':'新增'}`)};m.onclick=e=>{if(e.target===m)m.classList.remove('show')}}
